import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-d1-001","clusterId":"D","werkstueckRef":"D.1.1","stufe":2,"question":"Was ist an diesem Einwand der Kern des Denkfehlers, und was wäre der bessere nächste Schritt?","scenario":"In einer Diskussion über den Klimawandel sagt jemand: „Die Studie, die du zitierst, wurde von einem Ölkonzern finanziert. Damit ist sie wertlos.“ Die Studie selbst hat er nicht gelesen.","options":["Er schließt allein aus der Finanzierung, dass die Daten falsch sind. Besser: die Geldgeber als Anlass für genaues Hinsehen nehmen und Methode und Daten selbst prüfen.","Er urteilt über eine Studie, die er nicht gelesen hat. Besser: sie erst lesen und darin nach Spuren suchen, wie stark der Ölkonzern ihre Ergebnisse geprägt hat.","Er nennt den Geldgeber, belegt aber keine Einflussnahme. Besser: erst nachweisen, dass der Konzern auf die Ergebnisse der Studie eingewirkt hat, bevor man die Studie verwirft.","Er misstraut der Studie zu Recht, denn Interessen färben Ergebnisse. Besser: sie vorerst beiseitelegen und sich nur auf Studien stützen, die ohne Industriegeld entstanden sind."],"correctIndex":0,"explanation":"Wer bezahlt, kann ein Motiv für verzerrte Ergebnisse sein. Das ist ein guter Grund, die Studie besonders kritisch zu lesen, etwa auf Methodik, Datenlage und unabhängige Replikation zu achten. Ob die Daten falsch sind, folgt daraus aber nicht: Die Geldgeber sagen etwas über mögliche Interessen, nicht über die Richtigkeit der Messwerte. Zum Fehlschluss wird der Einwand, sobald die Frage nach der Finanzierung die Prüfung der Studie selbst ersetzt, statt sie zu ergänzen.","coreRule":"⚡ Wer bezahlt, ist ein Grund zum Genauhinsehen – ein Gegenbeweis ist es nicht.","beleg":"Werkstück D.1.1 (Formen des Ad-hominem-Angriffs: interessenbasiert; Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer bezahlt, kann ein Motiv für Verzerrung haben, aber ob die Messwerte stimmen, zeigt erst die Studie selbst. Der Fehler: Die Frage nach dem Geldgeber ersetzt die Prüfung, statt sie zu schärfen. Besser: Methodik, Daten und Replikation ansehen.","prueffrage":"Hat der Sprecher irgendetwas am Inhalt der Studie beanstandet, oder stützt sich sein ganzer Einwand auf den Geldgeber?","rueckmeldung":[{"option":1,"text":"Die Studie vor dem Urteil zu lesen, ist tatsächlich nötig. Aber auch beim Lesen nur nach Spuren des Geldgebers zu suchen, hielte die Finanzierung wieder für den eigentlichen Maßstab; entscheidend bleiben Methode, Datenlage und Replikation."},{"option":2,"text":"Voreilig verwerfen sollte man die Studie tatsächlich nicht. Die Pflicht, erst Einflussnahme zu belegen, kehrt aber die Reihenfolge um: Man darf genauer hinsehen, sobald es einen Anlass gibt, und prüft dann die Studie selbst."},{"option":3,"text":"Dass Interessen Ergebnisse färben können, ist ein berechtigter Anlass für Vorsicht. Daraus folgt aber Prüfen statt Aussortieren, und auch Studien ohne Industriegeld sind nicht automatisch zuverlässig, sodass das Ausweichen auf sie die Prüfung nicht ersetzt."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge Ad Hominem, Circumstantial Ad Hominem)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"45c65a8443533f66"}},{"id":"qx-d1-002","clusterId":"D","werkstueckRef":"D.1.1","stufe":1,"question":"Welche Antwort bleibt beim Argument der Chemikerin und weicht nicht auf die Person aus?","scenario":"In einer Online-Diskussion über die Sicherheit eines neuen Haushaltsreinigers antwortet jemand auf den Hinweis einer Chemikerin, der Wirkstoff sei laut Prüfbericht in der üblichen Dosierung unbedenklich.","options":["„Als Chemikerin lebst du von der Chemie, also wundert es mich nicht, dass du die übliche Dosierung für unbedenklich hältst.“","„Lass uns den Prüfbericht gemeinsam ansehen: Wie wurde die Dosierung festgelegt, und welche Testbedingungen wurden verwendet?“","„Dass du den Prüfbericht so selbstsicher zitierst, zeigt nur, dass du Kritik an der Chemie nicht ertragen kannst.“","„Ausgerechnet du, die selbst mit Chemikalien arbeitet, willst mir etwas über eine unbedenkliche Dosierung erzählen?“"],"correctIndex":1,"explanation":"Ob ein Wirkstoff in der üblichen Dosierung unbedenklich ist, hängt an den Daten und der Methode des Prüfberichts, nicht an der Person, die darauf hinweist. Die Antwort, die nach Dosierung und Testbedingungen fragt, prüft genau das und bleibt bei der Sache. Die Glaubwürdigkeit einer Quelle zu hinterfragen kann legitim sein, widerlegt das Argument aber nicht automatisch.","coreRule":"⚡ Prüfe, was gesagt wird, nicht, wer es sagt: Beschimpfung, Motivunterstellung und Heuchelei-Vorwurf führen weg von der Sache und hin zur Person.","quote":"Die logische Gültigkeit oder Falschheit eines Arguments hängt niemals von den Eigenschaften der Person ab, die es ausspricht.","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.1 (Kontext & Tiefe: abusive, Tu quoque, circumstantial)","status":"entwurf","kurz":"Ob die Dosierung unbedenklich ist, entscheiden Daten und Methode des Prüfberichts, nicht die Person, die darauf hinweist. Wer nach Testbedingungen und Festlegung der Dosierung fragt, prüft genau das; wer beim Beruf oder Verhalten ansetzt, trifft nur die Chemikerin.","prueffrage":"Worauf bezieht sich die Antwort: auf das, was im Bericht steht, oder auf die Person, die ihn nennt?","rueckmeldung":[{"option":0,"text":"Vorsicht gegenüber Eigeninteressen kann berechtigt sein. Doch der Beruf sagt nichts darüber, wie der Prüfbericht zustande kam oder ob seine Daten tragen, und so bleibt das Argument selbst unberührt."},{"option":2,"text":"Hier wird ihr Verhalten gedeutet statt der Bericht geprüft. Aus selbstsicherem Zitieren folgt weder, dass sie Kritik nicht erträgt, noch etwas über die Dosierung. Die Daten bleiben ungeprüft."},{"option":3,"text":"Arbeit mit Chemikalien kann Erfahrung bedeuten, macht ihren Hinweis aber weder richtiger noch falscher. Ob die übliche Dosierung unbedenklich ist, zeigt sich im Prüfbericht, nicht in ihrem Beruf."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge Ad Hominem, Circumstantial Ad Hominem, Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d8d3e4c5e75bfee0"}},{"id":"qx-d1-003","clusterId":"D","werkstueckRef":"D.1.1","stufe":3,"question":"Welche Reaktion ist die sachlich richtige Antwort auf diese Lage?","options":["Die Finanzierung ist ein Grund, die Studie genau zu prüfen, aber ob die Daten stimmen, zeigt erst die Analyse von Methode und Ergebnissen.","Die Finanzierung entwertet die Studie vorerst; erst wenn eine unabhängig bezahlte Studie zum selben Ergebnis kommt, zählen auch ihre Daten.","Die Finanzierung macht ein Ergebnis zugunsten des Mittels wenig glaubwürdig; der Teilnehmer sagt es zu scharf, hat in der Sache aber recht.","Die Finanzierung sollte beiseitebleiben, weil der Ruf „gekauft“ die Person angreift; fair ist es, über Methode und Daten der Studie selbst zu sprechen."],"correctIndex":0,"explanation":"Motive und Geldgeber zu prüfen ist legitim: Sie sind ein guter Grund für besonders kritisches Lesen. Zum Fehlschluss wird es, wenn diese Prüfung die Auseinandersetzung mit dem Argument ersetzt. Ein Interessenkonflikt beweist nicht, dass die Daten falsch sind. Das zeigt sich nur an der Analyse der Studie selbst: Ist das Argument in sich stimmig, und wird es von Beweisen gestützt?","coreRule":"⚡ Die Glaubwürdigkeitsprüfung ergänzt die Prüfung des Arguments, sie ersetzt sie nie.","beleg":"Werkstück D.1.1 (Der Kipppunkt; Das Adaptive Talent)","status":"entwurf","scenario":"In einer Diskussion über ein neues Pflanzenschutzmittel stellt eine Wissenschaftlerin Studiendaten vor, nach denen das Mittel unbedenklich ist. Du erfährst, dass ihr Institut vom Hersteller finanziert wird. Ein Teilnehmer ruft: „Die Studie ist damit erledigt, die Frau ist ja gekauft!“","kurz":"Die Finanzierung ist ein guter Grund, die Studie besonders kritisch zu lesen. Ob die Daten stimmen, zeigt aber erst die Analyse von Methode und Ergebnissen, denn ein Interessenkonflikt allein widerlegt keine Daten.","prueffrage":"Worauf stützt der Teilnehmer sein Urteil „erledigt“: auf etwas in den Daten oder allein auf den Geldgeber?","rueckmeldung":[{"option":1,"text":"Dass unabhängige Studien das Vertrauen stärken, stimmt. Die Daten gelten aber nicht erst dann, wenn jemand anderes sie bestätigt: Ob sie tragen, lässt sich schon an Methode und Ergebnissen dieser Studie prüfen."},{"option":2,"text":"Finanzierung darf Misstrauen wecken und ist ein Grund, genauer hinzusehen. Sie sagt aber nichts darüber, ob die Daten stimmen. Wer bei der Herkunft stehen bleibt, ersetzt die Prüfung des Arguments durch ein Urteil über die Geldgeber."},{"option":3,"text":"Daran stimmt: „Gekauft“ greift die Person an, und über Methode und Daten zu sprechen ist richtig. Den Geldgeber auszublenden geht aber zu weit, denn er ist ein berechtigter Grund, besonders kritisch zu lesen."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Circumstantial Ad Hominem)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"3c185d696b65569a"}},{"id":"qx-d1-004","clusterId":"D","werkstueckRef":"D.1.1","stufe":4,"question":"Was ist an deiner Folgerung das Problem?","scenario":"Dein Bekannter sagt: „Schau dir diesen heißen Sommer an – der Klimawandel ist real!“ Du antwortest: „Das ist Wetter, nicht Klima – also ist wohl nichts dran an der Erwärmung.“","options":["Nichts: Wer einen Fehler im Argument nachweist, hat damit gezeigt, dass die behauptete Schlussfolgerung falsch ist.","Dein Hinweis ist selbst falsch: Wetter und Klima zu verwechseln ist eine zulässige Abkürzung und kein Denkfehler.","Dein Hinweis ist selbst ein Fehlschluss: Wer einem Argument ein Etikett anheftet, ohne es zu begründen, widerlegt damit nichts.","Dein Hinweis trifft nur das Argument: Ein Fehler darin macht die Behauptung des Bekannten nicht automatisch falsch."],"correctIndex":3,"explanation":"Der Bekannte verwechselt Wetter und Klima, sein Argument ist also fehlerhaft. Ein fehlerhaftes Argument stützt seine Behauptung nicht, aber es widerlegt sie auch nicht: Ob eine Behauptung stimmt, hängt von der Sache und den Belegen ab, nicht davon, wer sie vorbringt oder wie schlecht das Argument dafür gebaut ist. Ob sie stimmt, zeigt erst die Prüfung der Sache selbst, etwa langjährige Temperaturreihen statt eines einzelnen Sommers. Wer aus dem Fehler schließt, an der Erwärmung sei nichts dran, springt zu früh. Dein Hinweis auf die Verwechslung ist berechtigt, aber er beantwortet nur die Frage, ob das Argument taugt, nicht die Frage, ob die Behauptung stimmt.","coreRule":"⚡ Ein Fehler im Argument widerlegt nicht die Behauptung – prüfe die Sache selbst.","beleg":"Werkstück D.1.1 (Ad Hominem), Abschnitte „Kontext & Tiefe“ und „Der Kipppunkt“; keine Fußnote","status":"zurueckgezogen","kurz":"Der Hinweis auf die Verwechslung von Wetter und Klima ist berechtigt, trifft aber nur das Argument. Dass ein Argument schlecht ist, macht die Behauptung nicht falsch: Sie kann trotzdem stimmen, und das zeigt erst die Prüfung der Sache selbst.","prueffrage":"Was sagen langjährige Temperaturreihen, wenn du sie neben diesen einen Sommer legst?","rueckmeldung":[{"option":0,"text":"Einen Fehler im Argument zu finden, fühlt sich wie eine Widerlegung an. Er zeigt aber nur, dass dieser Grund nicht trägt. Die Behauptung kann aus einem schlechten Grund vorgebracht werden und trotzdem stimmen."},{"option":1,"text":"Hier liegt die Abkürzung nahe, weil beides mit dem Himmel über uns zu tun hat. Dein Hinweis ist aber berechtigt: Ein einzelner heißer Sommer ist Wetter, Klima meint langfristige Entwicklungen. Das Problem liegt im Schluss, den du daraus ziehst."},{"option":2,"text":"Ein bloßes Etikett widerlegt tatsächlich nichts. Dein Hinweis ist aber keines, sondern begründet: Ein einzelner Sommer sagt über das Klima wenig. Das Problem liegt beim Schluss auf die Erwärmung, nicht beim Hinweis selbst."}],"familie":"fehlschluss-macht-nichts-falsch","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Validity and Soundness“ (anonymer Verfasser)","oeffentlich":true,"url":"https://iep.utm.edu/val-snd/","abruf":"2026-10-12"},{"typ":"doi","kurz":"IPCC (2021): Summary for Policymakers. Climate Change 2021: The Physical Science Basis, WG I, AR6","oeffentlich":true,"doi":"10.1017/9781009157896.001","seite":"Abschnitt A.1.2","abruf":"2026-10-04"},{"typ":"literatur","kurz":"Novella, S. u. a. (2018): The Skeptics' Guide to the Universe, Kap. 10, Abschnitt „Fallacy Fallacy“ (E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"streichen","pruefsumme":"d0b7a61df01a82aa"}},{"id":"qx-d1-005","clusterId":"D","werkstueckRef":"D.1.2","stufe":1,"question":"Welche Antwort prüft am besten, ob die Erwiderung deines Bruders deinen Vorschlag trifft?","scenario":"Du sagst beim Familienessen: „Ich fände es schön, wenn wir abends ab und zu ohne Handys essen.“ Dein Bruder erwidert: „Du willst uns also das Handy verbieten und alle zurück in die Steinzeit schicken?“","options":["Ich würde fragen: „Habe ich ein Verbot gefordert?“ Damit lege ich meinen tatsächlichen Satz neben seine Wiedergabe und vergleiche, ob beide zusammenpassen.","Ich würde fragen: „Wie oft liegen bei uns abends beim Essen Handys auf dem Tisch?“ Damit prüfe ich, wie groß das Problem ist, das mein Vorschlag lösen soll.","Ich würde fragen: „Gibt es Untersuchungen, ob Familien ohne Handys am Tisch mehr miteinander reden?“ Damit prüfe ich, ob mein Vorschlag sachlich begründet ist.","Ich würde fragen: „Wer achtet darauf, dass sich alle an handyfreie Abende halten, und was passiert bei Verstößen?“ Damit prüfe ich, ob mein Vorschlag im Alltag umsetzbar ist."],"correctIndex":0,"explanation":"Aus „ab und zu ohne Handys essen“ macht dein Bruder „Handy verbieten“ und „zurück in die Steinzeit“. Er widerlegt damit nicht deinen Vorschlag, sondern eine übertriebene Version davon: ein Strohmann. Am besten prüfst du das, indem du deinen Satz wörtlich neben seine Wiedergabe legst und fragst, ob sie zusammenpassen. So wird sichtbar, dass er auf etwas antwortet, das du nicht gesagt hast.","coreRule":"⚡ Prüfe, ob widerlegt wird, was gesagt wurde, oder nur, was sich bequem widerlegen lässt.","quote":"Du fühlst den Drang zu sagen: „Aber das habe ich doch gar nicht gesagt!“","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.2 (Kernidee; Formen des Strohmanns: Übertreibung; Red Flags)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"ff7d91ecd6acd603","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Der Bruder antwortet auf „Handy verbieten“ und „Steinzeit“, gesagt hast du „ab und zu ohne Handys essen“. Das lässt sich prüfen, indem du deinen Satz neben seine Wiedergabe legst: Passen beide nicht zusammen, widerlegt er nur eine übertriebene Version, einen Strohmann.","prueffrage":"Welche Abende und wie viele Mahlzeiten wären von deinem Vorschlag überhaupt betroffen?","rueckmeldung":[{"option":1,"text":"Wie oft Handys am Tisch liegen, zeigt, wie dringend dein Vorschlag sein könnte. Ob dein Bruder dich richtig wiedergibt, bleibt dabei aber offen, denn das hängt nur an deinen Worten und seiner Wiedergabe."},{"option":2,"text":"Die Frage nach Untersuchungen ist berechtigt, wenn du deinen Vorschlag begründen willst. Sie prüft aber den Vorschlag selbst und nicht, ob die Erwiderung ihn trifft; dafür zählt nur, was du gesagt hast und was dein Bruder daraus macht."},{"option":3,"text":"Wer auf die Einhaltung achtet und was bei Verstößen passiert, ist später wichtig. Zuerst muss aber klar sein, worüber ihr redet, und die Frage nach Kontrolle und Strafen passt eher zu dem Verbot, das dein Bruder in deinen Satz hineinliest."}],"familie":"strohmann-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false,"seite":"S. 144 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ff7d91ecd6acd603"}},{"id":"qx-d1-006","clusterId":"D","werkstueckRef":"D.1.2","stufe":2,"question":"Welche Rückfrage prüft am besten, ob dieser Text eine tragfähige Begründung für die Methode liefert?","scenario":"In einem Werbetext für eine alternative Methode steht: „Die Schulmedizin sieht den Menschen nur als Maschine und interessiert sich nicht für die Seele. Wir dagegen behandeln den ganzen Menschen.“ Eine Leserin findet den Text überzeugend und überlegt, die Methode auszuprobieren.","options":["Ob die Schulmedizin so arbeitet, wie der Text behauptet, und was für die eigene Methode belegt wird","Ob die Methode Körper und Seele wirklich zusammen behandelt, wie es der Text für sich in Anspruch nimmt","Ob die Leserin bei Ärzten selbst schon erlebt hat, dass sich niemand für ihr seelisches Befinden interessierte","Ob die Verfasser des Textes am Verkauf der dort beworbenen Methode womöglich selbst etwas verdienen"],"correctIndex":0,"explanation":"Der Text baut ein Zerrbild der Schulmedizin auf und widerlegt dann dieses Zerrbild: Er ignoriert die umfangreiche psychosomatische Forschung und die Bemühungen vieler Ärzte um eine ganzheitliche Betrachtung, um die eigene „alternative“ Methode als einzig empathische darzustellen. Das ist ein Strohmann-Argument. Daraus folgt für die Leserin: Auch ein widerlegtes Zerrbild sagt noch nichts darüber, ob die eigene Methode wirkt. Die richtige Rückfrage prüft deshalb beides: ob die Darstellung des Gegners fair ist und ob für die eigene Methode überhaupt etwas belegt wird.","coreRule":"⚡ Wer die Gegenseite nur als Zerrbild zeigt, hat über die eigene Sache noch nichts bewiesen.","beleg":"Werkstück D.1.2 (Anwendung & Relevanz: In der Pseudomedizin)","status":"entwurf","kurz":"Der Text widerlegt ein Zerrbild der Schulmedizin und sagt damit noch nichts über die eigene Methode. Ob er trägt, zeigt sich also an zwei Dingen: Ist die Darstellung der anderen Seite fair, und wird für die eigene Methode überhaupt etwas belegt?","prueffrage":"Wie viele Sätze des Textes handeln von der Schulmedizin, und wie viele davon, was die angebotene Methode bewirkt?","rueckmeldung":[{"option":1,"text":"Dass die Methode das Ganzheitliche nur behauptet, verdient durchaus Skepsis. Selbst wenn sie es einlöst, bleibt aber offen, ob das Bild der Schulmedizin stimmt und ob die Methode wirkt. Ganzheitlich ist nicht automatisch wirksam."},{"option":2,"text":"Eigene Erfahrungen mit Ärzten können sehr real sein und verdienen Beachtung. Sie sagen aber nur etwas über einzelne Begegnungen, nicht über die Schulmedizin insgesamt, und schon gar nichts darüber, ob die beworbene Methode hilft."},{"option":3,"text":"Ein finanzielles Interesse ist bei Werbung ein guter Grund zur Vorsicht. Es macht das Argument aber weder richtig noch falsch: Geprüft wird dann die Absicht der Verfasser, nicht, ob Zerrbild und fehlender Beleg den Schluss tragen."}],"familie":"strohmann-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false,"seite":"S. 144 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"c943696ab8e823d5"}},{"id":"qx-d1-007","clusterId":"D","werkstueckRef":"D.1.2","stufe":3,"question":"Wie reagierst du am klügsten?","scenario":"In der Teambesprechung schlägst du vor, die Wochenberichte um eine Seite zu kürzen. Ein Kollege ruft: „Du willst also jede Dokumentation abschaffen!“ Mehrere im Raum nicken, die Stimmung kippt.","options":["Die Sitzung kurz unterbrechen und den Vorschlag, die Wochenberichte um eine Seite zu kürzen, später schriftlich neu einreichen, damit sich die Stimmung beruhigt.","Kurz wiedergeben, wie du den Einwand verstanden hast, und dann in einem Satz klarstellen, dass du nur eine Seite weniger pro Wochenbericht vorgeschlagen hast.","Die Vorteile kürzerer Wochenberichte hervorheben und vorrechnen, wie viel Zeit das dem Team für die eigentliche Arbeit lässt, damit der Vorschlag überzeugt.","Zustimmen, dass die Wochenberichte für das Team wichtig sind, und den Vorschlag so weit abschwächen, dass er niemanden im Raum mehr stört."],"correctIndex":1,"explanation":"Der Kollege hat nicht auf deinen Vorschlag geantwortet, sondern auf eine übertriebene Fassung davon: ein Strohmann. Am wirksamsten ist es, die Verzerrung sichtbar zu machen und die Debatte zu deiner tatsächlichen Aussage zurückzuführen. Das gelingt, wenn du seine Fassung neutral zurückspiegelst und deinen Punkt klarstellst. Oft reicht diese sanfte Konfrontation schon, um den Angreifer zum Zurückrudern zu bewegen.","coreRule":"⚡ Spiegle den Strohmann neutral zurück und führe die Debatte zu deiner tatsächlichen Aussage.","quote":"Das ist eine interessante Kritik, aber sie richtet sich nicht gegen das, was ich gesagt habe. Mein eigentlicher Punkt war...","quoteLabel":"Beispielantwort:","beleg":"Werkstück D.1.2 (Das Anti-Denkmuster: Aktivierungs-Frage)","status":"entwurf","kurz":"Der Kollege hat auf eine übertriebene Fassung deines Vorschlags geantwortet. Gib seine Version neutral zurück und stelle klar, was du wirklich meinst: Dann ist die Verzerrung sichtbar, und die Debatte kehrt zu deiner eigentlichen Aussage zurück.","prueffrage":"Beziehen sich die Einwände im Raum auf das, was du gesagt hast, oder auf etwas, das erst danach daraus gemacht wurde?","rueckmeldung":[{"option":0,"text":"Eine Pause kann die Stimmung beruhigen. Die falsche Darstellung bleibt aber im Raum stehen, und ein späteres Nachreichen korrigiert sie nicht: Bis dahin gilt dein Vorschlag als „alles abschaffen“."},{"option":2,"text":"Gute Argumente und Zahlen helfen, wenn über den echten Vorschlag gesprochen wird. Gerade wird aber über eine übertriebene Fassung gestritten, und die Vorteile gehen daran vorbei. Erst die Verzerrung klären, dann argumentieren."},{"option":3,"text":"Rücksicht auf die Stimmung wirkt vernünftig. Niemand hat deinen Vorschlag aber widerlegt, er wurde nur falsch wiedergegeben. Ihn abzuschwächen gibt einen Punkt auf, der nie angegriffen wurde."}],"familie":"strohmann-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false,"seite":"S. 144 und 150 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"47f42c1f31cbc980"}},{"id":"qx-d1-008","clusterId":"D","werkstueckRef":"D.1.2","stufe":4,"question":"Was solltest du tun, bevor du Jonas’ Vorschlag kritisierst, damit du nicht dasselbe tust wie Mara?","scenario":"Kollege Jonas sagt in der Teambesprechung: „Ich würde die Kernarbeitszeit etwas lockern, damit Eltern ihre Kinder morgens in Ruhe in die Kita bringen können.“ Deine Kollegin Mara antwortet empört: „Jonas will also, dass niemand mehr pünktlich im Büro ist und alle kommen und gehen, wann sie wollen!“ Du sollst gleich selbst auf Jonas’ Vorschlag antworten und möchtest dabei fair bleiben.","options":["Jonas’ Vorschlag in seiner stärksten Form mit eigenen Worten zusammenfassen und ihn bestätigen lassen, dass du ihn richtig verstanden hast.","Offenlegen, welche eigenen Interessen du an der Kernarbeitszeit hast, und erst dann Kritik äußern, damit niemand verdeckte Motive vermutet.","Mit Daten belegen lassen, wie viele Eltern im Team von einer Lockerung profitieren würden, und deine Kritik erst danach auf diese Zahlen stützen.","Klären, ob eine Lockerung der Kernarbeitszeit mit den geltenden Arbeitszeitregeln vereinbar ist, und deine Kritik an diesem Maßstab ausrichten."],"correctIndex":0,"explanation":"Mara hat nicht auf Jonas’ tatsächlichen Vorschlag geantwortet, sondern eine übertriebene Karikatur davon angegriffen: einen Strohmann. Das Gegenmittel ist die faire Rekonstruktion: Du gibst die Position des anderen in ihrer besten Form wieder und lässt sie bestätigen, bevor du sie kritisierst. Dann kann kein Strohmann entstehen, und deine Kritik trifft den echten Vorschlag. Eigene Interessen an der Kernarbeitszeit offenzulegen ist fair, ändert aber nichts daran, ob du Jonas richtig wiedergibst. Zahlen dazu, wie viele Eltern profitieren, helfen bei der Bewertung, setzen aber voraus, dass der Vorschlag richtig verstanden ist. Die Prüfung der Arbeitszeitregeln ist ein eigener Schritt, der erst sinnvoll ist, wenn klar ist, was genau vorgeschlagen wurde.","coreRule":"⚡ Gib die Position des Gegners in ihrer stärksten Form wieder, bevor du sie kritisierst – dann kann kein Strohmann entstehen.","beleg":"Werkstück D.1.2 (Formen des Strohmanns; Verbindungen: Stahlmann-Argument; Fußnote gl-d-strohmann: Principle of Charity, Bowell/Kemp 2002)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"37d24913584a3ada","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Mara hat eine Karikatur angegriffen statt Jonas’ Vorschlag. Das vermeidest du, indem du seine Position in bester Form mit eigenen Worten wiedergibst und bestätigen lässt, bevor du kritisierst. Dann trifft deine Kritik den echten Vorschlag.","prueffrage":"Welchen Zweck nennt Jonas, und wie weit soll die Lockerung nach seinen Worten gehen?","rueckmeldung":[{"option":1,"text":"Eigene Interessen offenzulegen ist fair und schafft Vertrauen. Es ändert aber nichts daran, ob du Jonas richtig wiedergibst: Auch mit offenen Karten kannst du eine verzerrte Version seines Vorschlags kritisieren."},{"option":2,"text":"Zahlen zum Nutzen können später bei der Bewertung helfen. Sie setzen aber voraus, dass du den Vorschlag richtig verstanden hast, und verhindern allein nicht, dass du eine Zerrform davon angreifst."},{"option":3,"text":"Ob die Arbeitszeitregeln eine Lockerung zulassen, ist eine eigene Frage, die erst Sinn ergibt, wenn klar ist, was genau vorgeschlagen wurde. Als Schutz vor einem Strohmann taugt sie nicht."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge (Principle of Charity)","oeffentlich":false,"seite":"S. 43–47, S. 144 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"37d24913584a3ada"}},{"id":"qx-d1-009","clusterId":"D","werkstueckRef":"D.1.3","stufe":2,"question":"Wie lässt sich seine Antwort in dieser Lage am treffendsten einordnen?","scenario":"Bei der Mitgliederversammlung deines Sportvereins stellt der Vorsitzende einen Reformplan vor. Als du fragst, ob die Kosten schon durchgerechnet sind, antwortet er: „Wer nicht Teil der Lösung ist, ist Teil des Problems.“ Du hältst den Plan für unausgereift, hast aber selbst noch keinen besseren Vorschlag. Die meisten Mitglieder haben sich noch keine feste Meinung gebildet.","options":["Der Satz ist eine gängige Redewendung, die zum Mitmachen ermuntern soll; als Antwort auf deine Frage nach den Kosten ist er nur etwas ungeschickt gewählt.","Der Satz ist berechtigt, denn wer wie du keinen eigenen Vorschlag vorlegt, hält den bisherigen Zustand im Verein fest und stützt damit das Problem.","Der Satz verrät, dass die Kosten nicht durchgerechnet sind; hätte der Vorsitzende belastbare Zahlen, hätte er sie genannt, statt auszuweichen.","Der Satz lässt nur Mitmachen oder Blockieren zu; dass du den Plan erst prüfen und verbessern willst, ohne das Problem zu stützen, fehlt darin."],"correctIndex":3,"explanation":"Der Satz presst die Lage in ein Entweder-oder: Wer den Plan unterstützt, ist Teil der Lösung, wer ihn nicht unterstützt, Teil des Problems. Dabei fällt unter den Tisch, dass man einen Plan für unausgereift halten kann, ohne schon eine bessere Lösung zu haben, etwa weil man ihn erst verbessern oder das Problem genauer verstehen will; deine Frage nach den Kosten ist genau so ein Schritt. Das macht niemanden zum Teil des Problems. Der Fehlschluss heißt falsches Dilemma; er funktioniert, weil Kritik an der einen Seite automatisch als Zustimmung zur anderen gedeutet wird. Ein prüfender Gegenzug ist die Frage: „Welche weiteren Möglichkeiten gibt es neben diesen beiden?“ Den Satz für berechtigt zu halten, übernimmt gerade dieses Entweder-oder, obwohl du den Plan nicht blockierst, sondern nachfragst.","coreRule":"⚡ Wer nur zwei Plätze anbietet, hat die übrigen Möglichkeiten schon aus dem Raum geschoben.","beleg":"Werkstück D.1.3 (Anwendung & Relevanz: Im Alltag; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Der Satz kennt nur Mitmachen oder Blockieren. Dabei kannst du einen Plan für unausgereift halten und trotzdem nur nachfragen und verbessern wollen, ohne etwas zu blockieren. Aus Kritik wird so scheinbar Zustimmung zur Gegenseite.","prueffrage":"Welche Haltungen zum Plan gibt es noch außer „dafür“ und „dagegen“?","rueckmeldung":[{"option":0,"text":"Der Satz ist wirklich eine geläufige Redewendung und kann zum Mitmachen ermuntern. Hier beantwortet er aber deine Kostenfrage nicht, sondern sortiert dich in ein Lager ein, und das wirkt auf Unentschlossene stärker, als „ungeschickt“ vermuten lässt."},{"option":1,"text":"Wer nur verhindert und nichts beiträgt, löst tatsächlich kein Problem. Du blockierst aber nichts, sondern fragst nach den Kosten, und das ist ein Beitrag zum Plan. Die Antwort setzt voraus, dass es nur Lösung oder Problem gibt, und genau das trägt nicht."},{"option":2,"text":"Ausweichen auf eine Sachfrage kann ein Warnzeichen sein. Warum der Vorsitzende so antwortet, lässt sich aber aus einem Satz nicht sicher ablesen: Eile, Ungeduld oder der Wunsch nach Zustimmung kommen ebenso in Frage. Der Fehler liegt in der Form der Antwort."}],"familie":"falsches-dilemma","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge False Dilemma, Black-or-White)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"cae92b1c4ec689f7"}},{"id":"qx-d1-010","clusterId":"D","werkstueckRef":"D.1.3","stufe":3,"question":"Beide Aussagen sind Entweder-oder-Aussagen, aber nur eine davon ist ein Falsches Dilemma. Woran erkennst du, welche?","scenario":"Im Gemeinderat sagt ein Redner zur geplanten Umgehungsstraße: „Entweder bauen wir die Straße genau so, wie sie jetzt geplant ist, oder unser Ort erstickt im Verkehr. Wer dagegen stimmt, will den Stau.“ Auf einem Formular der Gemeinde steht dagegen die Frage: „Wurde die Gebühr bezahlt? Ja oder Nein.“","options":["Daran, ob nur zwei Möglichkeiten genannt werden: Wer genau zwei Optionen gegenüberstellt, verengt die Auswahl und begeht ein Falsches Dilemma.","Daran, ob eine Entscheidung verlangt wird: Wer wie der Redner oder das Formular eine Antwort einfordert, zwingt zur Wahl und begeht ein Falsches Dilemma.","Daran, ob es weitere Möglichkeiten gibt, die verschwiegen werden: Die Zweiteilung wird dann künstlich aufgezwungen und engt den Denkraum ein.","Daran, ob sich die beiden Möglichkeiten ausschließen: Wer nur zwei sich ausschließende Wege lässt, zwingt zur Wahl und begeht ein Falsches Dilemma."],"correctIndex":2,"explanation":"Ein echtes Dilemma gibt es nur, wenn tatsächlich nur zwei Möglichkeiten bestehen, etwa bei „Leben oder Tod“. Die Gebühr ist entweder bezahlt oder nicht, das Formular ist also unproblematisch. Beim Redner im Gemeinderat gibt es dagegen mehr Möglichkeiten: Er verschweigt sie, damit seine Variante als einzig vernünftige Wahl erscheint, und stempelt Kritik als Wunsch nach dem Stau ab. Entscheidend ist also nicht die Form „Entweder-oder“, sondern ob es wirklich keine dritte Möglichkeit gibt oder ob sie nur ausgeblendet wird.","coreRule":"⚡ Prüfe nicht die Form „Entweder-oder“, sondern ob es wirklich keine dritte Möglichkeit gibt.","beleg":"Werkstück D.1.3 (Kontext & Tiefe: echtes Dilemma; Der Kipppunkt)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"d54ba3bae0d79347","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Entscheidend ist nicht die Form „Entweder-oder“, sondern ob es wirklich keine dritte Möglichkeit gibt. Beim Formular stimmt das, beim Redner werden weitere Wege nur ausgeblendet, damit seine Variante alternativlos wirkt.","prueffrage":"Was haben beide Aussagen gemeinsam: Verlangen beide eine Entscheidung, und klingt in beiden eine der Möglichkeiten unangenehm?","rueckmeldung":[{"option":0,"text":"Der Redner nennt tatsächlich nur zwei Möglichkeiten. Das tut das Formular aber ebenso, ohne dass dort etwas schiefläuft. Die Zahl der genannten Möglichkeiten trennt die Fälle nicht; es kommt darauf an, ob es weitere gäbe."},{"option":1,"text":"Beide Aussagen verlangen etwas von dir: eine Entscheidung oder eine Antwort. Das ist aber an sich kein Fehler, denn auch das unproblematische Formular tut es. Eine Antwort einzufordern macht eine Aussage noch nicht zum Dilemma."},{"option":3,"text":"Dass sich die beiden Wege ausschließen, stimmt bei Redner und Formular gleichermaßen. Deshalb unterscheidet es die beiden Fälle nicht. Ob sich zwei Möglichkeiten ausschließen, sagt noch nichts darüber, ob daneben weitere bestehen."}],"familie":"falsches-dilemma","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Black-or-White)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"d54ba3bae0d79347"}},{"id":"qx-d1-011","clusterId":"D","werkstueckRef":"D.1.3","stufe":4,"question":"Wie beurteilst du diesen Einwand am besten?","scenario":"In einem Forum wird behauptet: „Bush hat nach dem 11. September 2001 gesagt: ‚Wer nicht für uns ist, ist gegen uns.‘ Das ist ein Lehrbuchbeispiel für ein Falsches Dilemma.“ Ein anderer Nutzer antwortet: „Das Zitat ist so wohl nicht korrekt. Im Transkript der Rede vor dem Kongress vom 20. September 2001 steht: ‚Either you are with us, or you are with the terrorists.‘ Dein Beispiel taugt also nichts.“","options":["Der Einwand betrifft nur den Wortlaut: Auch das Original bietet nur zwei Optionen an, daher bleibt es ein Falsches Dilemma.","Der Einwand widerlegt die Behauptung, denn mit einem ungenauen Zitat ist auch die Einordnung als Falsches Dilemma hinfällig geworden.","Der Einwand ist unerheblich, denn bei einem Beispiel für einen Fehlschluss kommt es nur auf die ungefähre Aussage an, nicht auf den genauen Wortlaut.","Der Einwand zeigt, dass der Originalsatz kein Falsches Dilemma ist, denn „mit den Terroristen“ ist inhaltlich eine andere Aussage als „gegen uns“."],"correctIndex":0,"explanation":"Zwei Dinge müssen getrennt werden: ob das Zitat stimmt und ob die Struktur ein Falsches Dilemma ist. Der Einwand prüft nur die Kongressrede vom 20. September 2001: Laut Transkript lautet der Satz dort „Either you are with us, or you are with the terrorists.“ Dem Forumssatz entspricht aber, was Bush am 6. November 2001 bei einer Pressekonferenz mit Frankreichs Präsident Chirac sagte: „You are either with us or you are against us in the fight against terror.“ (Transkript des Weißen Hauses). [Im Feld quellen ergänzen: https://georgewbush-whitehouse.archives.gov/news/releases/2001/11/20011106-4.html, abgerufen 2026-10-14; den CNN-Beleg im Feld beleg dadurch ersetzen oder nachrangig stellen.] Für die Einordnung kommt es auf den Wortlaut ohnehin nicht an: Beide Sätze bieten nur zwei Möglichkeiten an, eine dritte oder neutrale Haltung ist nicht vorgesehen. Ein ungenaues Zitat macht die Einordnung also nicht falsch, es verlangt nur, das Beispiel am Original zu belegen. Wer Fehlschlüsse benennt, sollte genau zitieren, und wer widerspricht, sollte prüfen, ob der Einwand die Kernaussage überhaupt trifft.","coreRule":"⚡ Prüfe bei einem Einwand, ob er die Struktur des Arguments trifft oder nur ein Detail wie das Zitat, und belege Beispiele am Originalwortlaut.","beleg":"Werkstück D.1.3 (Anwendung & Relevanz: In der Politik); Fn. gl-d-bush911 (Bush, Address to a Joint Session of Congress, 20.09.2001, Transkript des Weißen Hauses). Pressekonferenz mit Chirac, 6.11.2001: CNN, „You are either with us or against us“, https://edition.cnn.com/2001/US/11/06/gen.attack.on.terror/ (abgerufen 12.10.2026); wiedergegeben auch bei Monshipouri (2012): Terrorism, Security, and Human Rights, Lynne Rienner, Anm. 10.","status":"entwurf","kurz":"Der Einwand prüft nur die Kongressrede; einen fast gleichen Satz sagte Bush am 6. November 2001. Und selbst bei falschem Wortlaut bliebe es ein Falsches Dilemma: Auch der Satz der Kongressrede bietet nur zwei Möglichkeiten an.","prueffrage":"Bei welchen Gelegenheiten hat Bush ähnliche Sätze gesagt, und wo steht jeweils der genaue Wortlaut?","rueckmeldung":[{"option":1,"text":"Ein ungenaues Zitat lässt das ganze Beispiel erledigt wirken. Ob eine Aussage nur zwei Möglichkeiten zulässt, zeigt sich aber an ihrer Form, und die steckt auch im Satz der Kongressrede. Nötig ist ein genauer Beleg, nicht das Ende des Beispiels."},{"option":2,"text":"Dass der Kern gleich bleibt, stimmt: Beide Fassungen kennen nur zwei Lager. Genau deshalb lässt sich das Beispiel retten. Daraus folgt aber nicht, dass der Wortlaut egal ist; wer einen Fehlschluss anprangert, muss ihn am echten Satz belegen."},{"option":3,"text":"Die beiden Formulierungen sind tatsächlich nicht gleichbedeutend. Dieser Unterschied ändert aber nichts an der Zweiteilung: Auch „mit uns oder mit den Terroristen“ lässt keinen Platz für eine neutrale oder dritte Haltung."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"The White House (2001): President Declares „Freedom at War with Fear“, Address to a Joint Session of Congress and the American People, 20.09.2001","oeffentlich":true,"url":"https://georgewbush-whitehouse.archives.gov/news/releases/2001/09/20010920-8.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag False Dilemma)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3de7cdd1dc4896ae"}},{"id":"qx-d1-012","clusterId":"D","werkstueckRef":"D.1.4","stufe":1,"question":"Wie solltest du auf das Argument deines Onkels am besten reagieren?","scenario":"Ein berühmter Literatur-Nobelpreisträger erklärt in einem Interview, ein neuer Impfstoff sei unsicher. Dein Onkel meint: „Dem Mann sollte man glauben, er hat schließlich einen Nobelpreis.“ Studien zum Impfstoff kennt dein Onkel nicht.","options":["Du fragst, ob der Preisträger in der Impfstoffforschung Fachwissen hat und welche Daten er vorlegt, denn das Gewicht einer Aussage hängt an Zuständigkeit und Belegen.","Du fragst, ob der Literaturnobelpreis zu Recht an ihn vergeben wurde, denn nur dann kann man den Aussagen des Preisträgers über den Impfstoff vertrauen.","Du fragst, ob der Preisträger sonst auch zu gesellschaftlichen Fragen klug Stellung nimmt, denn wer in einem Feld Urteilskraft zeigt, urteilt auch in anderen gut.","Du fragst, ob mehrere Medien die Warnung des Preisträgers vor dem Impfstoff aufgegriffen haben, denn eine weit verbreitete Aussage ist besser abgesichert."],"correctIndex":0,"explanation":"Ein Preis belegt Können nur in dem Fach, in dem er erworben wurde. Wer Literatur auf Weltklasseniveau beherrscht, ist deshalb noch kein Fachmann für Impfstoffe. Ob eine Aussage über einen Impfstoff stimmt, entscheiden Daten aus Studien, nicht der Name dessen, der sie ausspricht. Dein Onkel ersetzt hier den Beweis durch einen Verweis auf eine Person, und zwar auf eine, deren Fachgebiet gar nicht zur Frage passt. Die beste Reaktion fragt deshalb nach Zuständigkeit und nach Belegen. Ob der Preis zu Recht vergeben wurde, ändert nichts daran, dass er für ein anderes Fach vergeben wurde. Kluge Stellungnahmen zu gesellschaftlichen Fragen machen ihn nicht zum Impfstoffexperten, denn Sachkenntnis überträgt sich nicht von selbst von einem Feld aufs andere. Und wie viele Medien eine Warnung aufgreifen, sagt nichts darüber, ob sie stimmt.","coreRule":"⚡ Ein Rang beweist nur etwas in dem Fach, in dem er erworben wurde.","quote":"Er ersetzt den **Beweis (die Daten)** durch einen **Verweis (den Experten)**.","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.4 (Kernidee: Hauptformen des Fehlschlusses)","status":"entwurf","kurz":"Ein Preis belegt Können nur in seinem Fach, und ob ein Impfstoff unsicher ist, zeigen Studien, nicht ein Name. Der Onkel ersetzt den Beweis durch eine Person, die gar nicht zuständig ist. Besser fragst du nach Fachwissen und Belegen.","prueffrage":"Wofür wurde der Preis verliehen, und wer hat den Impfstoff bisher in Studien untersucht?","rueckmeldung":[{"option":1,"text":"Die Frage nach der Preiswürdigkeit klingt nach Quellenprüfung. Sie geht aber am Kern vorbei: Selbst ein hochverdienter Literaturpreis wurde für ein anderes Fach vergeben und sagt nichts darüber, ob der Impfstoff sicher ist."},{"option":2,"text":"Wer sich zu gesellschaftlichen Fragen klug äußert, wirkt auch in anderen Dingen glaubwürdig. Sachkenntnis überträgt sich aber nicht von selbst auf ein anderes Feld, und beim Impfstoff entscheiden Studien, nicht allgemeine Urteilskraft."},{"option":3,"text":"Viel Medienecho zeigt, dass die Warnung Aufmerksamkeit bekommt. Ob sie stimmt, sagt es nicht: Eine Aussage wird nicht richtiger, weil sie oft wiederholt wird, und ein bekannter Name bringt sie schnell in die Schlagzeilen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"43179d807b226ace"}},{"id":"qx-d1-013","clusterId":"D","werkstueckRef":"D.1.4","stufe":2,"question":"Welche Rückfrage bringt die Debatte am besten weiter?","scenario":"In einer Debatte über Vitamin C und Krebs stellst du fest, dass es dafür keine robusten Belege aus kontrollierten Studien gibt. Dein Gegenüber antwortet: „Linus Pauling, ein zweifacher Nobelpreisträger, hat hochdosiertes Vitamin C gegen Krebs vehement vertreten. Willst du es etwa besser wissen als er?“","options":["Wofür hat Pauling seine beiden Nobelpreise bekommen, und gehört die Behandlung von Krebs überhaupt zu seinem eigenen Fachgebiet?","Welche Daten hat Pauling für hochdosiertes Vitamin C gegen Krebs vorgelegt, und lassen sich diese in kontrollierten Studien bestätigen?","Hat Pauling in der Chemie gezeigt, dass er sorgfältig arbeitet, sodass man auch seiner Aussage über Vitamin C gegen Krebs ruhig trauen darf?","Gibt es Fachleute für Krebsmedizin, die Paulings Empfehlung zu hochdosiertem Vitamin C teilen, oder steht er damit allein da?"],"correctIndex":1,"explanation":"Der Einwand setzt eine Person an die Stelle der Daten. Paulings Nobelpreise waren für Chemie (1954) und Frieden (1962), nicht für Medizin. Entscheidend ist, was kontrollierte Studien zeigen: Gegen fortgeschrittenen Krebs half hochdosiertes Vitamin C zum Einnehmen nicht (Moertel u. a. 1985); Infusionen mit weit höheren Blutspiegeln werden noch erforscht. Die beste Antwort lenkt daher von der Person zur Evidenz: Welche Daten gibt es, und halten sie einer Prüfung stand? Man kann jemanden respektieren und trotzdem verlangen, dass die Behauptung durch Daten gedeckt ist.","coreRule":"⚡ Respekt vor der Person ersetzt nicht den Blick auf die Daten.","beleg":"Werkstück D.1.4 (Einstiegsszene); Fn. gl-d-pauling (Nobelstiftung: Chemie 1954, Frieden 1962; Moertel u. a. 1985, NEJM 312(3), S. 137–141; Padayatty u. a. 2004; NCI (Infusionen))","status":"entwurf","kurz":"Wer einen Namen anführt, ersetzt Daten durch eine Person. Weiter bringt die Frage, welche Daten es für die Behauptung gibt und ob kontrollierte Studien sie bestätigen. Das geht, ohne Pauling den Respekt abzusprechen.","prueffrage":"Wofür genau hat Pauling seine beiden Nobelpreise bekommen?","rueckmeldung":[{"option":0,"text":"Pauling hat seine Preise tatsächlich für Chemie und Frieden erhalten, nicht für Medizin. Die Frage bleibt aber bei der Person: Auch ein Fachmann müsste seine Behauptung mit Daten belegen, und ein Außenseiter könnte recht haben."},{"option":2,"text":"Sorgfalt in der Chemie ist ein Ruf in einem anderen Fach und sagt nichts darüber, ob diese Behauptung durch Daten gedeckt ist. So wird die Autorität nur ins Positive gewendet, statt die Belege zu prüfen."},{"option":3,"text":"Fachliche Zustimmung ist oft ein nützlicher Hinweis, aber gezählt werden hier Meinungen statt Daten. Ob viele oder wenige Fachleute zustimmen, sagt noch nicht, was kontrollierte Studien zeigen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Moertel, C. G. u. a. (1985): High-dose vitamin C versus placebo in the treatment of patients with advanced cancer who have had no prior chemotherapy. NEJM 312(3), 137–141","oeffentlich":true,"doi":"10.1056/NEJM198501173120301","url":"https://pubmed.ncbi.nlm.nih.gov/3880867/","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: Intravenous High-Dose Vitamin C (PDQ®), Fachfassung, Stand 13.05.2025","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/treatment/cam/hp/vitamin-c-pdq","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"f76fe34b7a86f30a"}},{"id":"qx-d1-014","clusterId":"D","werkstueckRef":"D.1.4","stufe":3,"question":"Wie verhält sich dein eigenes Vertrauen in Hausarzt und Pilotin zum Argument deines Bekannten?","scenario":"Du lässt dich vom Hausarzt beraten, ohne sein Diplom zu prüfen, und steigst ins Flugzeug, ohne die Lizenz der Pilotin zu kontrollieren. Später zitiert ein Bekannter einen angesehenen Professor für Pharmakologie mit einer Aussage über die Wirkung eines Medikaments. Als du fragst, auf welche Studien sich die Aussage stützt, antwortet er: „Der Mann ist Professor, wer bist du, das zu bezweifeln?“","options":["Der Unterschied liegt in der Quelle: Hausarzt und Pilotin erlebst du selbst, die Aussage des Professors kennst du nur aus zweiter Hand.","Der Unterschied liegt im Nachfragen: Hausarzt und Pilotin dürftest du nach Belegen fragen, beim Bekannten soll der Titel diese Frage ersetzen.","Beides ist derselbe Fehler: Auch bei Hausarzt und Pilotin ersetzt du die Prüfung der Belege durch dein Vertrauen in eine Person mit Titel oder Lizenz.","Der Unterschied liegt im Aufwand: Bei Hausarzt und Pilotin wäre eigenes Prüfen kaum zu leisten, die Studien zum Medikament könntest du selbst lesen."],"correctIndex":1,"explanation":"Wir können nicht alles selbst wissen. Vertrauen an (hoffentlich) evidenzbasierte Fachleute zu delegieren ist die Grundlage unserer arbeitsteiligen Gesellschaft. Dein Vertrauen in Hausarzt und Pilotin bleibt ein Wegweiser zur Evidenz: Du könntest nachfragen, und die Belege würden der Prüfung standhalten. Zum Fehlschluss wird es, wenn die Person an die Stelle der Daten tritt und die Frage „Was weißt du?“ durch „Wer bist du, das zu bezweifeln?“ ersetzt wird – genau das tut dein Bekannter, als du nach den Studien fragst. Dann dient die Autorität nicht mehr als Hinweis auf Belege, sondern als Totschlagargument; eine legitime Expertenmeinung wird zum unfehlbaren Beweis, der jede Nachfrage verbietet (Autorität als Dogma). Reputation ist nicht Evidenz. Entscheidend ist nicht, ob du selbst alles prüfst, sondern ob Nachfragen nach den Belegen erlaubt bleiben. Jedes Vertrauen ohne eigene Prüfung zum Fehler zu erklären, verkennt diese Arbeitsteilung.","coreRule":"⚡ Vertrauen in Fachleute ist klug – solange die Frage nach der Evidenz erlaubt bleibt.","quote":"","quoteLabel":"","beleg":"Werkstück D.1.4 (Kontext & Tiefe: Logik vs. Heuristik; Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Dein Vertrauen in Hausarzt und Pilotin bleibt ein Wegweiser zu Belegen, denn du dürftest nachfragen. Zum Fehlschluss wird es, wenn ein Titel die Nachfrage ersetzt, wie bei deinem Bekannten.","prueffrage":"Was geschieht in jedem der Fälle, wenn du nach den Belegen fragst?","rueckmeldung":[{"option":0,"text":"Dass du die Aussage nur aus zweiter Hand kennst, stimmt. Auch bei Arzt und Pilotin vertraust du aber auf Fachleute, ohne selbst zu prüfen. Entscheidend ist, ob Nachfragen nach Belegen erlaubt bleiben."},{"option":2,"text":"Titel und Lizenz allein sind tatsächlich keine Belege. Vertrauen ohne eigene Prüfung ist aber nicht von sich aus ein Fehler: Es bleibt ein Wegweiser zur Evidenz, solange du nachfragen könntest."},{"option":3,"text":"Selbst alles zu prüfen wäre bei Arzt und Pilotin tatsächlich kaum zu leisten. Entscheidend ist aber nicht, wer wie viel selbst prüft, sondern ob die Frage nach den Belegen erlaubt bleibt."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"13222d0083e88cbf"}},{"id":"qx-d1-015","clusterId":"D","werkstueckRef":"D.1.4","stufe":4,"question":"Was ist an dieser Begründung fehlerhaft?","scenario":"Im Netz heißt es: „Dr. Müller ist ein mutiger Abtrünniger, den die ‚Mainstream-Wissenschaft‘ mundtot macht. Gerade weil er den Fachleuten widerspricht, müssen seine Thesen stimmen.“","options":["Sie ersetzt Belege durch eine Abwertung der Fachleute, denn sie nennt sie „Mainstream“, statt auf ihre Gründe einzugehen.","Sie ersetzt Belege durch starke Gefühlswörter, denn „mutig“ und „mundtot“ sollen die Leser für Müller einnehmen.","Sie ersetzt Belege durch die Person Müllers, denn Widerspruch gegen Fachleute sagt allein nichts über seine Thesen.","Sie ersetzt Belege durch ein Entweder-oder, denn sie tut so, als könne nur Müller oder die Fachwelt recht haben."],"correctIndex":2,"explanation":"Auch die Umkehrung des Autoritätsarguments ist ein Fehlschluss: Statt Daten wird die Person des „mutigen Abtrünnigen“ als Beweis angeführt. Dass jemand der Fachgemeinschaft widerspricht, macht seine Thesen weder wahr noch falsch. Entscheidend bleibt, welche Belege er vorlegt und wie die gesamte Fachgemeinschaft sie bewertet.","coreRule":"⚡ Widerspruch zum Konsens ist kein Beweis – auch der Außenseiter braucht Daten.","beleg":"Werkstück D.1.4 (Kontext & Tiefe: Die Autoritäts-Umkehrung; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Dass jemand der Fachwelt widerspricht, sagt nichts darüber, ob seine Thesen stimmen. Wer den Abtrünnigen selbst zum Beweis macht, ersetzt Daten durch Person; entscheidend bleibt, welche Belege er vorlegt und wie die Fachgemeinschaft sie bewertet.","prueffrage":"Was erfährst du aus dem Beitrag über den Inhalt von Müllers Thesen?","rueckmeldung":[{"option":0,"text":"Dass „Mainstream-Wissenschaft“ abwertend klingt, stimmt, und auf ihre Gründe geht das Zitat tatsächlich nicht ein. Der Kern des Fehlers liegt aber woanders: Müllers Rolle als Abtrünniger wird selbst zum Beweis gemacht."},{"option":1,"text":"„Mutig“ und „mundtot“ sind tatsächlich emotional gefärbt und sollen einnehmen. Würde man sie durch nüchterne Wörter ersetzen, bliebe der Fehlschluss aber bestehen: Müllers Widerspruch gegen die Fachleute soll schon seine Thesen belegen."},{"option":3,"text":"Das Zitat stellt Müller und die Fachwelt gegeneinander. Es verlangt aber nicht, dass nur eine Seite recht haben kann; Müller könnte auch teilweise richtigliegen. Der Fehler liegt im Schluss vom Widerspruch auf Wahrheit, denn der sagt für sich nichts über seine Thesen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"54ece4e4985d9141"}},{"id":"qx-d1-016","clusterId":"D","werkstueckRef":"D.1.5","stufe":1,"question":"Wie gehst du mit seinem Gegenvorwurf am sinnvollsten um?","scenario":"Du sprichst deinen Mitbewohner darauf an, dass sein Rechner und der Fernseher jede Nacht durchlaufen, obwohl niemand sie benutzt. Er kontert: „Du lässt doch selbst dauernd das Licht im Flur brennen!“ Das stimmt: Du vergisst das Flurlicht tatsächlich oft.","options":["Du räumst das Flurlicht ein und bleibst dabei, dass Rechner und Fernseher nachts nicht durchlaufen müssen.","Du ziehst deine Kritik an Rechner und Fernseher zurück, bis du das Flurlicht selbst verlässlich ausschaltest.","Du hältst ihm vor, er lenke nur ab, und gehst auf das Flurlicht nicht ein, um beim eigentlichen Thema zu bleiben.","Du lässt das Thema ruhen, weil ihr beide Strom verschwendet und sich eure Vorwürfe damit gegenseitig aufheben."],"correctIndex":0,"explanation":"Das ist ein Tu quoque („du auch“): Ob eine Kritik zutrifft, hängt von ihrer Logik und den Belegen ab, nicht davon, ob der Sprecher selbst konsequent handelt. Ob Rechner und Fernseher nachts unnötig laufen, entscheidet sich an diesen Geräten, auch wenn du im Flur das Licht brennen lässt. Deshalb kannst du das Flurlicht ehrlich einräumen und trotzdem bei deiner Kritik bleiben: Dein Licht verdient vielleicht ein eigenes Gespräch, beantwortet aber nicht die Frage, ob seine Geräte unnötig Strom verbrauchen. Die Kritik zurückzuziehen klingt fair, macht aber deine eigene Konsequenz zur Bedingung dafür, dass sie stimmt.","coreRule":"⚡ Ob jemand selbst danach lebt, entscheidet nicht, ob seine Aussage stimmt.","quote":"Ein Mörder, der sagt „Morden ist falsch“, hat immer noch Recht.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück D.1.5 (Kernidee; Kontext & Tiefe: Logische Ungültigkeit)","status":"entwurf","kurz":"Ob Rechner und Fernseher nachts unnötig laufen, entscheidet sich an den Geräten, nicht an deinem Flurlicht. Wer mit „du auch“ kontert, verschiebt die Frage auf den Sprecher; du kannst das Licht einräumen und bei deiner Kritik bleiben.","prueffrage":"Würde sich an den laufenden Geräten etwas ändern, wenn du im Flur nie das Licht brennen ließest?","rueckmeldung":[{"option":1,"text":"Die Kritik zurückzunehmen wirkt fair, weil du dann nicht mit zweierlei Maß misst. Dann hängt aber ihre Berechtigung an deinem eigenen Verhalten, obwohl sie sich allein daran entscheidet, ob die Geräte unnötig laufen."},{"option":2,"text":"Beim eigentlichen Thema zu bleiben ist richtig. Das Flurlicht zu übergehen, obwohl der Hinweis stimmt, wirkt aber unehrlich. Du kannst es einräumen und trotzdem bei den Geräten bleiben; dein Licht darf später ein eigenes Gespräch bekommen."},{"option":3,"text":"Zwei Fälle von Stromverschwendung heben sich nicht auf, sie addieren sich eher. Ob die Geräte nachts unnötig laufen, bleibt eine offene Frage, die sich an den Geräten klärt, und lässt sich nicht durch Schweigen erledigen."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"793c38bba0ba1374"}},{"id":"qx-d1-017","clusterId":"D","werkstueckRef":"D.1.5","stufe":2,"question":"Was ist die beste Reaktion von A auf diesen Konter?","scenario":"In einer Diskussion sagt A: „Euer Land lässt Menschen in Haft schlecht behandeln, das muss sich ändern.“ B antwortet sofort: „Und was ist mit eurer Polizeigewalt? Darüber redet ihr natürlich nie!“ Der Vorwurf der Polizeigewalt gegen das Land von A trifft tatsächlich zu; zu den Haftbedingungen im eigenen Land sagt B aber nichts.","options":["A wertet das Schweigen von B zu den Haftbedingungen als Eingeständnis und hält die Kritik damit für bewiesen, weil ein unbestrittener Vorwurf als zugegeben gilt.","A erkennt die Polizeigewalt als ernstes, eigenes Thema an, bleibt aber bei den Haftbedingungen, weil der Gegenvorwurf die ursprüngliche Kritik nicht entkräftet.","A schlägt vor, dass beide ihre Vorwürfe zu Haftbedingungen und Polizeigewalt zurückziehen, weil sich die gegenseitige Kritik ausgleicht und ein Neuanfang möglich wird.","A stellt die Kritik an den Haftbedingungen zurück und kümmert sich zuerst um die Polizeigewalt im eigenen Land, weil man erst vor der eigenen Tür kehren sollte."],"correctIndex":1,"explanation":"Dass der Gegenvorwurf zutrifft, ändert nichts an der Gültigkeit der ursprünglichen Kritik: Er verdient eine eigene Diskussion, entkräftet den ersten Punkt aber nicht. Diese Ablenkung nennt man Whataboutism, eine Form des „Du auch“-Fehlschlusses: Er verschiebt das Gespräch von der Sachebene auf die Frage, ob der Sprecher moralisch konsistent ist. Das Ziel ist oft nicht, das eigene Handeln zu rechtfertigen, sondern den Kritiker zum Schweigen zu bringen und ein Patt zu erzeugen. Am besten erkennt man das andere Problem an, trennt es aber vom ersten und kehrt zur offenen Frage zurück.","coreRule":"⚡ Ein anderer Missstand ist ein anderes Thema – er entlastet den ersten nicht.","beleg":"Werkstück D.1.5 (Kontext & Tiefe: Whataboutism; Das Anti-Denkmuster: Skript 2)","status":"entwurf","kurz":"Dass der Gegenvorwurf stimmt, entkräftet die erste Kritik nicht, sondern verschiebt das Gespräch auf die Frage, wer konsequent ist. Am besten nimmt A das andere Problem ernst, trennt es vom ersten und kehrt zu den Haftbedingungen zurück.","prueffrage":"Über welchen Missstand in welchem Land hat A gesprochen, und worüber spricht B in seiner Antwort?","rueckmeldung":[{"option":0,"text":"Dass B zu den Haftbedingungen schweigt, wirkt wie ein Zugeständnis, ist aber keines. Ob die Kritik stimmt, entscheidet sich an den Haftbedingungen selbst, nicht daran, was B dazu nicht sagt."},{"option":2,"text":"Ein gegenseitiger Rückzug klingt fair und nach einem Neuanfang. Er lässt aber offen, wie es den Menschen in Haft ergeht, und begräbt zugleich einen berechtigten Vorwurf, obwohl beide Probleme bestehen bleiben."},{"option":3,"text":"Zuerst vor der eigenen Tür zu kehren, wirkt bescheiden, und die Polizeigewalt verdient tatsächlich Aufmerksamkeit. Das ist aber ein eigenes Thema. Wer mit Kritik wartet, bis das eigene Haus in Ordnung ist, verbietet sich und anderen jede Kritik."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"0c2a72f25f2dd1c7"}},{"id":"qx-d1-018","clusterId":"D","werkstueckRef":"D.1.5","stufe":3,"question":"Welche Reaktion nutzt den Heuchelei-Vorwurf berechtigt und nicht als Tu-quoque-Fehlschluss?","options":["„Seine 80 000 Euro sind erfunden, denn wer selbst mit dem Dienstwagen in Urlaub fährt, rechnet unehrlich.“","„Seine Dienstwagen-Regel ist unsinnig, denn er fährt ja selbst mit seinem Dienstwagen in den Urlaub.“","„Ich wähle ihn nicht, denn wer Sparsamkeit fordert und mit dem Dienstwagen urlaubt, ist unglaubwürdig.“","„Die Stadt muss nichts ändern, denn ihr schärfster Kritiker fährt ja selbst mit dem Dienstwagen in Urlaub.“"],"correctIndex":2,"explanation":"Ein Heuchelei-Vorwurf ist berechtigt, wenn es um die Glaubwürdigkeit oder Eignung einer Person geht, etwa bei der Frage, ob man sie in ein Amt wählt. Zum Fehlschluss wird er, sobald er ein Tatsachenargument widerlegen soll. Wer Berger wegen seiner Urlaubsfahrt nicht wählt, urteilt über seine Eignung für das Amt, und dafür ist sein Verhalten von Belang. Ob die Stadt 80 000 Euro zu viel ausgibt, ob die Dienstwagen-Regel sinnvoll ist und ob die Stadt etwas ändern muss, hängt dagegen an Zahlen und Belegen, nicht am Lebenswandel dessen, der es sagt. Die drei anderen Reaktionen klingen nach berechtigter Empörung, richten sie aber gegen Sachaussagen statt gegen die Person als Kandidaten; die letzte lenkt wie beim Whataboutism, einer Form des Tu quoque, mit dem Fehlverhalten des Kritikers von der Sachfrage ab. Ein Mörder, der „Morden ist falsch“ sagt, hat trotz seiner Heuchelei recht.","coreRule":"⚡ Heuchelei darf die Wahl einer Person beeinflussen, aber nie die Wahrheit ihrer Sachaussagen.","beleg":"Werkstück D.1.5 (Der Kipppunkt: legitim vs. Fehlschluss; Anwendung & Relevanz)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"cf96161a0cc583b7","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Der Vorwurf trifft Bergers Glaubwürdigkeit als Kandidat, und darüber darf man bei der Wahl urteilen. Zum Fehlschluss wird er erst, wenn sein Verhalten Zahlen oder Regel widerlegen soll, die an Belegen hängen.","prueffrage":"Worüber urteilst du gerade: über die Person, die du wählen sollst, oder über die Zahlen und die Regel?","rueckmeldung":[{"option":0,"text":"Die Urlaubsfahrt kann Misstrauen wecken, und dann lohnt es sich, die Zahlen nachzurechnen. Als Beleg gegen sie taugt sie aber nicht: Ob 80 000 Euro zu viel ausgegeben werden, lässt sich unabhängig davon prüfen, wer es sagt."},{"option":1,"text":"Dass er sich selbst nicht an die Regel hält, ist peinlich für ihn. Ob die Regel sinnvoll ist, hängt aber an Kosten und Nutzen für die Stadt, nicht an seinem Verhalten. Eine gute Regel bleibt gut, auch wenn ihr Urheber sie bricht."},{"option":3,"text":"Dass ausgerechnet der Kritiker selbst gegen die Regel verstößt, ärgert zu Recht. Es beantwortet aber nicht, ob die Stadt zu viel ausgibt. Das Verhalten des Kritikers lenkt hier von den Zahlen ab, die unabhängig von ihm stimmen oder nicht stimmen."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"cf96161a0cc583b7"},"scenario":"Bürgermeisterkandidat Berger fordert, städtische Dienstwagen nur noch für Dienstfahrten zu nutzen. Er legt Zahlen vor, nach denen die Stadt dafür jährlich 80 000 Euro zu viel ausgibt. Kurz darauf wird bekannt, dass er selbst mit seinem Dienstwagen in den Urlaub gefahren ist. Vier Bürgerinnen und Bürger reagieren darauf."},{"id":"qx-d1-019","clusterId":"D","werkstueckRef":"D.1.5","stufe":4,"question":"Welche Antwort trifft den Punkt eures Gesprächs am besten?","scenario":"Deine Schwägerin will ihre Erkältung mit homöopathischen Globuli behandeln. Du sagst, Homöopathie habe keine plausible Wirkung. Sie antwortet: „Und die Todesfälle und Nebenwirkungen der Schulmedizin? Die Pharmaindustrie ist viel schlimmer!“ Nimm an, ihr Vorwurf gegen die Pharmaindustrie stimmt.","options":["Selbst wenn das stimmt, haben beide Seiten ihre Schwächen, also kommt es bei einer Erkältung auf die Wahl kaum noch an.","Selbst wenn das stimmt, sagt es nichts darüber, ob Globuli gegen deine Erkältung wirken; das zeigen nur ihre Belege.","Selbst wenn das stimmt, wären Globuli bei einer Erkältung wohl die harmlosere Wahl, und darauf kommt es hier an.","Selbst wenn das stimmt, ist auch die Schulmedizin fehlbar, und dann sind Globuli bei einer Erkältung einen Versuch wert."],"correctIndex":1,"explanation":"Der Konter wechselt von der Sachfrage („Wirken die Globuli?“) zu einem Gegenvorwurf gegen die Schulmedizin. Selbst wenn der Vorwurf gegen „Big Pharma“ zutrifft, beweist er nicht, dass Homöopathie wirkt. Ob sie wirkt, hängt allein an ihrer eigenen Plausibilität und Evidenz; darum lenkt die treffende Antwort genau auf diese Frage zurück. Gleichwertigkeit, ein Zurückstellen des Einwands oder ein Pluspunkt für die Globuli klingen nach fairem Abwägen. Sie setzen aber alle voraus, dass Fehler der einen Seite etwas über die Wirkung der anderen aussagen, und das tun sie nicht.","coreRule":"⚡ Die Fehler der anderen Seite sind kein Beleg für die eigene.","beleg":"Werkstück D.1.5 (Anwendung & Relevanz: Pseudomedizin & Esoterik)","status":"entwurf","kurz":"Der Vorwurf gegen die Pharmaindustrie ändert nichts an der eigentlichen Frage, ob Globuli wirken. Das hängt allein an ihrer eigenen Plausibilität und Evidenz, und Fehler der einen Seite sind kein Beleg für die andere.","prueffrage":"Auf welche Frage geht ihre Antwort ein, und ist das dieselbe Frage, die du gestellt hast?","rueckmeldung":[{"option":0,"text":"Dass auch die Medizin Schwächen hat, stimmt hier ja. Daraus folgt aber keine Gleichwertigkeit: Ob Globuli wirken, bleibt unbeantwortet, und sie bleibt es auch, wenn man beide Seiten als fehlbar ansieht."},{"option":2,"text":"Globuli selbst richten kaum Schaden an, das ist ein echter Punkt. Er beantwortet aber nicht, ob sie gegen die Erkältung helfen, und darum ging es. Harmlosigkeit ist noch keine Wirkung."},{"option":3,"text":"Dass die Schulmedizin fehlbar ist, trifft zu. Ein Pluspunkt für Globuli entsteht daraus nicht: Was sie bewirken, hängt an ihrer eigenen Plausibilität und Evidenz, nicht an den Fehlern anderer."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"9e6433bb6c92698b"}},{"id":"qx-d1-020","clusterId":"D","werkstueckRef":"D.2.1","stufe":1,"question":"Was wäre der sinnvollste nächste Schritt, bevor du dich entscheidest?","scenario":"Bei einer Infoveranstaltung eines Tierheims erzählt eine Rednerin ohne eine einzige Zahl von „Rocky“, einem zitternden, abgemagerten Hund, der bei jeder Berührung zusammenzuckte. Ein kurzes Video zeigt, wie Rocky nach Wochen der Pflege wieder mit dem Schwanz wedelt. Eingeblendet wird: „Für nur 50 Cent am Tag kannst du die nächste Erfolgsgeschichte schreiben.“ Im Publikum werden Portemonnaies gezückt. Du überlegst, ob du spenden sollst.","options":["Du prüfst, ob Rockys Geschichte wirklich stimmt, etwa durch Nachfrage nach Datum, Ort und tierärztlichem Befund des Hundes, bevor du die 50 Cent am Tag zusagst.","Du fragst nach belegbaren Angaben dazu, wie viel von den 50 Cent am Tag tatsächlich bei den Tieren ankommt und was das Tierheim damit bewirkt.","Du wartest bis morgen, damit sich die Rührung durch Rockys Video legt, und sagst die 50 Cent am Tag nur zu, wenn dich die Geschichte dann noch berührt.","Du bittest um weitere Geschichten wie die von Rocky, damit du dir ein vollständigeres Bild davon machen kannst, wofür die 50 Cent am Tag eingesetzt werden."],"correctIndex":1,"explanation":"Die Geschichte weckt Mitleid, und das ist verständlich. Sie beweist aber nichts über die Effizienz der Organisation: Sie zeigt nur, dass ein Tier gelitten hat und dass einem Einzelfall geholfen wurde, nicht ob das Tierheim insgesamt wirksam arbeitet. Die Emotion ist nicht das Problem; zum Fehlschluss wird sie, wenn sie Beweise und Logik ersetzt. Die Frage nach Mittelverwendung und Wirkung trennt die Gefühlslage vom eigentlichen Argument.","coreRule":"⚡ Eine bewegende Geschichte zeigt, dass jemand leidet – nicht, dass die Hilfe wirkt. Frage nach den Belegen, die auch ohne dein Gefühl gelten.","beleg":"Werkstück D.2.1 (Einstiegsszene „Die Rede im Tierheim“; Kontext & Tiefe: Appell an das Mitleid)","status":"entwurf","kurz":"Rockys Geschichte zeigt, dass einem Tier geholfen wurde, nicht ob das Tierheim insgesamt wirksam arbeitet. Wer das Mitgefühl nicht mit einem Beleg verwechseln will, fragt nach Mittelverwendung und Wirkung, denn die gelten unabhängig vom Gefühl.","prueffrage":"Was hast du bei der Veranstaltung über das Tierheim erfahren, abgesehen davon, wie es Rocky ergangen ist?","rueckmeldung":[{"option":0,"text":"Nachzufragen wirkt gründlich, und eine erfundene Geschichte wäre ein Problem. Doch selbst wenn alles stimmt, bleibt Rocky ein Einzelfall und sagt nichts darüber, wie wirksam das Tierheim insgesamt arbeitet."},{"option":2,"text":"Eine Nacht Abstand beruhigt das Gefühl, und das ist nicht verkehrt. Nur liegen morgen immer noch keine Belege vor: Die Entscheidung hinge weiter daran, ob dich die Geschichte berührt, nicht an Mittelverwendung und Wirkung."},{"option":3,"text":"Mehr Geschichten wirken wie ein breiteres Bild. Jede einzelne ist aber wieder ein Einzelfall, die Zahl der Beispiele ersetzt keinen Beleg, und über die Wirksamkeit des Tierheims insgesamt erfährst du so weiterhin nichts."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Emotions)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3fc3a7b6c388598f"}},{"id":"qx-d1-021","clusterId":"D","werkstueckRef":"D.2.1","stufe":2,"question":"Woran erkennst du hier am ehesten einen manipulativen emotionalen Appell?","scenario":"Ein Werbespot zeigt nachts einen dunklen Hausflur, ein Geräusch, eine zitternde Familie, dazu düstere Musik – und dann das Angebot, zweimal hintereinander eingeblendet: „Mit der Alarmanlage XY schlafen Sie wieder ruhig.“","options":["Der Spot arbeitet mit Bildern und Musik statt mit Text, daher ist er ein Fehlschluss.","Die Lösung passt genau zur geweckten Emotion, und Prüfbares fehlt.","Der Spot löst Angst aus, daher ist die Bedrohung übertrieben dargestellt.","Der Spot wiederholt seine Botschaft mehrfach, daher ist er ein emotionaler Appell."],"correctIndex":1,"explanation":"Ein auffälliges Muster ist, dass erst eine Angst geweckt und im selben Moment die passende „Lösung“ angeboten wird. Bilder, Musik und Gefühle sind für sich kein Fehler: Ein Appell, der auf einer soliden faktischen Grundlage steht und Emotionen nutzt, um zum Handeln zu bewegen, ist legitim. Zum Trugschluss wird er erst, wenn die Emotion die einzige Grundlage ist und das Fehlen von Fakten verschleiert. Dass der Spot Angst auslöst, sagt nichts darüber, ob die Bedrohung übertrieben ist. Dass er seine Botschaft wiederholt, ist kein Kriterium für Manipulation. Entscheidend ist also, ob außer dem Gefühl etwas Überprüfbares geboten wird.","coreRule":"⚡ Achte darauf, wer dir Angst macht – und was er dir im selben Moment verkauft.","beleg":"Werkstück D.2.1 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Verdächtig wird der Spot, weil er erst Angst weckt und im selben Moment die passende Lösung anbietet, ohne dass etwas Prüfbares geboten wird. Emotion allein ist kein Fehler; sie wird erst zum Trugschluss, wenn sie die einzige Grundlage ist.","prueffrage":"Was bliebe von dem Spot übrig, wenn man Bilder und Musik weglässt und nur den eingeblendeten Satz liest?","rueckmeldung":[{"option":0,"text":"Bilder und Musik sind erst einmal nur Gestaltungsmittel, kein Fehler. Auch ein Spot ohne viel Text kann sachlich überzeugen, wenn er Prüfbares bietet. Entscheidend ist, was hinter den Bildern steht, nicht das Medium."},{"option":2,"text":"Dass Angst ausgelöst wird, stimmt, sagt aber nichts über die Größe der Bedrohung: Auch eine reale Gefahr macht Angst. Aufschlussreicher ist, ob der Spot außer dem Gefühl noch etwas Überprüfbares liefert."},{"option":3,"text":"Wiederholung allein macht einen Appell nicht manipulativ, denn auch sachliche Werbung wiederholt ihre Botschaft. Aussagekräftig ist, ob außer dem Gefühl etwas Prüfbares geboten wird."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Emotions)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ab9519e414a528de"}},{"id":"qx-d1-022","clusterId":"D","werkstueckRef":"D.2.1","stufe":3,"question":"Auf welches Plakat trifft der Vorwurf eines emotionalen Trugschlusses tatsächlich zu?","scenario":"Eine Freundin nennt jeden Appell mit Bildern verschmutzter Flüsse „Emotionsmache“ und meint, schon die Bilder machten ihn unseriös. Ihr kommt an vier Plakaten verschiedener Umweltgruppen vorbei, die alle mit Fotos desselben Flusses werben.","options":["Das Plakat zeigt verendete Fische in Großaufnahme, die Passanten empören, und nennt die gemessenen Schadstoffwerte.","Das Plakat zeigt den verschmutzten Fluss, nennt die gemessenen Werte und bittet darunter um Spenden für die Reinigung.","Das Plakat zeigt den schäumenden Fluss mit der Zeile „Unser Fluss stirbt“ und nennt darunter die gemessenen Werte.","Das Plakat zeigt ein weinendes Kind am Ufer und behauptet ohne jeden Messwert, die Fabrik vergifte den Fluss."],"correctIndex":3,"explanation":"Dass ein Argument Gefühle auslöst, macht es noch nicht fehlerhaft. Gefühle sind oft der Antrieb, sich überhaupt mit einem wichtigen Thema zu befassen. Ein Appell, der auf soliden Fakten steht und Emotionen nutzt, um zum Handeln zu bewegen, ist legitim. Zum Trugschluss wird er erst, wenn die Emotion die einzige Grundlage ist und das Fehlen von Fakten verschleiert. Genau das tut das Plakat mit dem weinenden Kind: Es behauptet eine Vergiftung durch die Fabrik, legt aber keinen einzigen Messwert vor. Der Test: Würde die Behauptung auch dann noch gelten, wenn du die Gefühle beiseitelegst und nur die Belege betrachtest? Bei den drei anderen Plakaten tragen die gemessenen Werte das Argument; drastische Bilder, eine zugespitzte Zeile oder eine Spendenbitte machen es eindringlicher oder zeigen ein Eigeninteresse, widerlegen aber die Messwerte nicht und machen das Argument nicht schwächer.","coreRule":"⚡ Gefühl darf der Antrieb sein – das Argument muss auch ohne das Gefühl tragen.","beleg":"Werkstück D.2.1 (Der Kipppunkt; Kontext & Tiefe)","status":"entwurf","kurz":"Gefühle machen einen Appell nicht fehlerhaft; zum Trugschluss wird er erst, wenn die Emotion die einzige Grundlage ist und Belege fehlen. Das weinende Kind behauptet eine Vergiftung, ohne einen Messwert zu nennen.","prueffrage":"Was bliebe von der Behauptung des Plakats übrig, wenn du das Bild und alle Gefühle wegdenkst?","rueckmeldung":[{"option":0,"text":"Drastische Bilder können empören, und das wirkt schnell wie Manipulation. Hier stehen aber die gemessenen Schadstoffwerte auf dem Plakat, sie tragen das Argument. Die Großaufnahme macht es eindringlicher, aber nicht schwächer."},{"option":1,"text":"Eine Spendenbitte zeigt ein Eigeninteresse der Gruppe, und das macht misstrauisch. Die gemessenen Werte stehen aber da und bleiben davon unberührt. Ein Eigeninteresse widerlegt Belege nicht; ein emotionaler Trugschluss liegt deshalb nicht vor."},{"option":2,"text":"„Unser Fluss stirbt“ ist zugespitzt und gefühlsbetont. Das allein ist kein Fehler, solange die Behauptung auf etwas ruht, und das tut sie: Die gemessenen Werte stehen direkt darunter. Zuspitzung ersetzt sie nicht, sie ergänzt sie nur."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Emotions)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"465b4d51601aee05"}},{"id":"qx-d1-023","clusterId":"D","werkstueckRef":"D.2.2","stufe":1,"question":"Ein Kollege wendet ein: „Das ist doch völlig in Ordnung – gelogen hat der Manager nicht, es sind ja wirklich 50 Positionen.“ Was ist an dieser Verteidigung übersehen?","scenario":"Ein Manager kündigt eine „Freisetzung von Personalressourcen im Umfang von 50 Positionen“ an. Tatsächlich verlieren 50 Menschen ihren Job. In der Belegschaft klingt die Ankündigung deutlich weniger bedrohlich, als wenn der Manager gesagt hätte, 50 Mitarbeiter würden gekündigt.","options":["Dass eine Aussage ohne falsche Tatsache trotzdem lenken kann: Dieselbe Realität in milderen Worten verändert den Eindruck, ohne eine Lüge zu sein.","Dass die milde Wortwahl doch eine Lüge ist: Wer von „Freisetzung“ statt von Kündigung spricht, stellt das Geschehen für die Betroffenen falsch dar.","Dass eine Halbwahrheit vorliegt: Die Ankündigung nennt nur Positionen und lässt weg, dass dahinter Menschen gekündigt werden; es fehlt also eine Tatsache.","Dass ein vager Begriff sich kaum prüfen lässt: Bei „Freisetzung von Personalressourcen“ bleibt offen, was genau geschieht, und damit auch, ob es stimmt."],"correctIndex":0,"explanation":"Der Kollege prüft nur, ob die Zahl stimmt. Das tut sie: Die Ankündigung nennt 50 Positionen, und tatsächlich verlieren 50 Menschen ihren Job. Die milde Formulierung lügt also nicht, färbt die Realität aber durch die Wahl der Worte um. Gelenkt wird nicht über die Zahl, sondern über die Wortwahl. „Freisetzung von Personalressourcen“ ersetzt eine harte Aussage durch milde, vage Begriffe. Das ist ein Euphemismus, ein Weichzeichner. Die Verteidigung vermischt zwei Fragen: „Ist es wahr?“ und „Wie wird mein Urteil gelenkt?“. Ein Test: Ersetze die Begriffe durch die neutralsten, sachlichsten Wörter, die du findest. Übrig bleibt: 50 Menschen verlieren ihre Stelle. Dass dieser Satz anders wirkt als die Ankündigung, zeigt, wie viel die Wortwahl bewirkt hat.","coreRule":"⚡ Ein Weichzeichner-Wort ändert den Eindruck, nicht die Tatsache.","beleg":"Werkstück D.2.2 (Einstiegsszene „Die Entscheidung des Managers“; „Kontext & Tiefe“, Punkt „Euphemismen (Die Weichzeichner)“; keine Fußnoten)","status":"entwurf","kurz":"Der Kollege prüft nur, ob die Zahl stimmt, und die stimmt. Gelenkt wird aber über die Wortwahl: Mildere Begriffe für dieselbe Realität verändern den Eindruck, ohne dass gelogen wird.","prueffrage":"Wie würde dieselbe Ankündigung klingen, wenn du nur die nüchternsten Wörter benutzt, die dir einfallen?","rueckmeldung":[{"option":1,"text":"Weil die Wortwahl so weich ist, liegt der Verdacht einer Lüge nahe. Die Angabe selbst stimmt aber: Es sind 50 Stellen, und 50 Menschen verlieren sie. Die Wirkung kommt aus der Färbung der Worte, nicht aus einer falschen Tatsache."},{"option":2,"text":"Dass die Ankündigung von Positionen statt von Menschen spricht, macht sie milder. Es fehlt aber keine Tatsache: Zahl und Stellenverlust sind korrekt benannt. Gelenkt wird über die Wortwahl, nicht über Weglassen."},{"option":3,"text":"Der Begriff ist tatsächlich vage und lässt sich leicht überhören. Die Aussage ist aber prüfbar und trifft zu: 50 Menschen verlieren ihre Stelle. Der Haken liegt daher nicht in der Unprüfbarkeit, sondern darin, wie die Wortwahl den Eindruck verschiebt."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Walker, A. C. u. a. (2021): Controlling the narrative: Euphemistic language affects judgments of actions while avoiding perceptions of dishonesty. Cognition 211, 104633","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104633","url":"https://pubmed.ncbi.nlm.nih.gov/33639377/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"29d18c7b938c1fd6"}},{"id":"qx-d1-024","clusterId":"D","werkstueckRef":"D.2.2","stufe":2,"question":"Was folgt aus dieser Konstellation für die Beurteilung der drei Berichte?","scenario":"Drei Nachrichtenportale berichten über denselben Mann, der mit Waffengewalt gegen eine Regierung kämpft. Portal A nennt ihn „Freiheitskämpfer“, Portal B „Terrorist“, Portal C „Aufständischer“. Alle drei melden dieselben Fakten: Ort, Zeitpunkt, Anzahl der Angriffe.","options":["Die drei Berichte sind gleichwertig, denn bei denselben Angaben zu Ort, Zeitpunkt und Angriffen wirken auch die Wörter gleich.","Die wertenden Wörter machen die Portale unzuverlässig, sodass auch ihre Angaben zu Ort, Zeitpunkt und Angriffen fraglich sind.","Mindestens zwei Portale liegen falsch, denn derselbe Mann kann nicht zugleich Freiheitskämpfer, Terrorist und Aufständischer sein.","Alle drei Wörter können auf denselben Mann mit denselben Angriffen passen, doch jedes legt schon ein bestimmtes Urteil nahe."],"correctIndex":3,"explanation":"Wörter haben eine Wörterbuch-Bedeutung (Denotation) und tragen zusätzlich Assoziationen (Konnotation). Alle drei Begriffe können auf denselben Mann passen, weil die Fakten übereinstimmen. Sie unterscheiden sich aber darin, ob sie ihn eher als Helden, als Schurken oder als neutralen Akteur erscheinen lassen. Das ist keine Lüge, aber eine Lenkung der Wahrnehmung: Das Urteil steckt schon im Wort. Wer die Berichte prüft, ersetzt die geladenen Wörter probeweise durch möglichst neutrale Beschreibungen („bewaffneter Kämpfer gegen die Regierung“) und fragt, was dann als nackte Tatsachenaussage übrig bleibt.","coreRule":"⚡ Wörter beschreiben nicht nur, sie urteilen schon mit.","beleg":"Werkstück D.2.2 (Kontext & Tiefe: Geladene Sprache – denotativ/konnotativ; Das Anti-Denkmuster)","status":"entwurf","kurz":"Alle drei Wörter können auf denselben Mann passen, weil die Fakten übereinstimmen. Aber jedes legt schon ein Urteil nahe: Wer nur auf die Tatsachen schaut, übersieht, dass das Urteil im Wort steckt.","prueffrage":"Was bleibt von jedem Bericht übrig, wenn du die Bezeichnung für den Mann durch eine bloße Beschreibung ersetzt?","rueckmeldung":[{"option":0,"text":"Gleiche Angaben zu Ort, Zeitpunkt und Angriffen sehen nach gleichen Berichten aus. Die Wörter wirken aber verschieden: Das eine macht den Mann zum Helden, das andere zum Schurken, das dritte bleibt neutral."},{"option":1,"text":"Gefärbte Wörter lenken tatsächlich die Wahrnehmung, und das verdient Misstrauen. Daraus folgt aber nicht, dass die Angaben falsch sind: Dass alle drei sie übereinstimmend melden, spricht eher für sie."},{"option":2,"text":"Ein Mann kann nicht Held, Schurke und neutrale Figur zugleich sein, wenn man die Wörter als Tatsachen liest. Sie sagen aber nichts anderes über seine Taten aus, sondern bewerten sie nur verschieden. Deshalb muss kein Portal falschliegen."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Walker, A. C. u. a. (2021): Controlling the narrative: Euphemistic language affects judgments of actions while avoiding perceptions of dishonesty. Cognition 211, 104633","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104633","url":"https://pubmed.ncbi.nlm.nih.gov/33639377/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"09c30d5cb3063f5d"}},{"id":"qx-d1-025","clusterId":"D","werkstueckRef":"D.2.2","stufe":3,"question":"Was ist an dem Einwand des Kollegen fehlerhaft, und woran erkennst du, wann ein Euphemismus tatsächlich manipulativ wird?","scenario":"In einer Pressemitteilung steht: „Im Rahmen einer Neuausrichtung setzen wir 50 Personalressourcen frei.“ Gleichzeitig sagt jemand aus der Belegschaft einer Kollegin, die einen Angehörigen verloren hat: „Er ist von uns gegangen.“ Ein Kollege meint: „Beides ist derselbe Trick, denn beides schwächt ein hartes Wort ab. Wer so redet, manipuliert.“","options":["Der Einwand stimmt, weil jeder Euphemismus die Wirklichkeit verschleiert; manipulativ ist er also schon beim ersten beschönigenden Wort.","Der Einwand verwechselt Beschönigung mit Täuschung; manipulativ wird ein Euphemismus erst, wenn er eine falsche Tatsache behauptet.","Der Einwand stimmt, solange der Sprecher ein Eigeninteresse hat; ob die Absicht taktvoll ist, spielt für die Einordnung keine Rolle.","Der Einwand setzt Ungleiches gleich; Taktgefühl ist unproblematisch, manipulativ wird Wortwahl erst, wenn sie die Realität verzerrt."],"correctIndex":3,"explanation":"Ein weicheres Wort ist für sich genommen noch keine Manipulation. „Er ist von uns gegangen“ statt „Er ist tot“ drückt Mitgefühl aus, und alle Beteiligten wissen, was gemeint ist. Die Pressemitteilung dagegen kleidet den Verlust von 50 Arbeitsplätzen in Begriffe wie „Neuausrichtung“ und „Personalressourcen“, sodass die Betroffenen und ihr Schicksal kaum noch erkennbar sind. Das kippt, wenn Sprache systematisch dazu dient, die Realität so zu verzerren, dass eine nüchterne Bewertung kaum noch möglich ist. Die Pressemitteilung muss dafür nicht lügen: Sie beschreibt dieselbe Realität wie die harte Fassung, färbt sie aber um, sodass die eine Fassung harmlos wirkt und die andere brutal. Ein Prüfstein ist, die geladenen Wörter durch die neutralsten zu ersetzen und zu fragen, was als nackte Aussage übrig bleibt. Beim Trauerfall bleibt dieselbe Aussage und niemand wird getäuscht; bei der Pressemitteilung wird erst dadurch sichtbar, was geschieht.","coreRule":"⚡ Rücksicht in der Wortwahl ist Höflichkeit – erst die systematische Verzerrung macht daraus Manipulation.","beleg":"Werkstück D.2.2 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Zwei weiche Formulierungen sind nicht dasselbe: „von uns gegangen“ ist taktvoll, und alle wissen, was gemeint ist. Manipulativ wird Wortwahl erst, wenn sie die Realität so verzerrt, dass eine nüchterne Bewertung kaum noch möglich ist.","prueffrage":"Wüsste jemand, der nur einen der beiden Sätze hört, jeweils genau, was den Betroffenen geschehen ist?","rueckmeldung":[{"option":0,"text":"Dass Euphemismen die Wirklichkeit abmildern, stimmt. Daraus folgt aber keine Manipulation: Beim Trauerfall drückt das weichere Wort Mitgefühl aus, und niemand wird über das Geschehene getäuscht."},{"option":1,"text":"Beschönigung und Täuschung auseinanderzuhalten, ist ein guter Ansatz. Zu eng ist nur die Bedingung: Eine Pressemitteilung muss nichts Falsches behaupten, um zu manipulieren. Es genügt, dieselbe Realität so umzufärben, dass sie harmlos wirkt."},{"option":2,"text":"Ein Eigeninteresse kann ein Anlass sein, genauer hinzusehen. Es macht eine Wortwahl für sich aber nicht manipulativ, und die Absicht spielt durchaus eine Rolle: Wer mit „von uns gegangen“ Anteilnahme zeigt, verzerrt nichts."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Walker, A. C. u. a. (2021): Controlling the narrative: Euphemistic language affects judgments of actions while avoiding perceptions of dishonesty. Cognition 211, 104633","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104633","url":"https://pubmed.ncbi.nlm.nih.gov/33639377/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"626e3063b100b9d7"}},{"id":"qx-d1-026","clusterId":"D","werkstueckRef":"D.2.2","stufe":4,"question":"Welche Prüfung hilft am besten, die Wirkung dieser Wortwahl zu durchschauen?","scenario":"Eine Broschüre schreibt: „Man leitet keine Gifte aus, man unterstützt den Körper bei seiner natürlichen Reinigung – ganzheitlich, sanft und harmonisierend.“","options":["Prüfen, ob „keine Gifte ausleiten“ und „den Körper bei der Reinigung unterstützen“ einander widersprechen, und den Satz bei einem Widerspruch zurückweisen.","Klären, wer die Broschüre verfasst hat und was er sich von der beworbenen Methode verspricht, und den Satz anhand dieser Interessen einordnen.","„Sanft“, „ganzheitlich“ und „harmonisierend“ probeweise durch neutrale Begriffe ersetzen und fragen, welche Tatsachenbehauptung übrig bleibt.","Im Wörterbuch nachschlagen, was „sanft“, „ganzheitlich“ und „harmonisierend“ bedeuten, und prüfen, ob der Satz sie angemessen verwendet."],"correctIndex":2,"explanation":"Wörter wie „sanft“, „ganzheitlich“ oder „harmonisierend“ transportieren ein Urteil, ohne etwas zu belegen. Ersetzt du sie probeweise durch neutrale Begriffe, siehst du, was tatsächlich behauptet wird: dass der Körper Stoffe ausscheidet und dass die beworbene Methode dabei hilft. Genau diese Behauptung lässt sich dann prüfen: Welcher Stoff? Wie nachgewiesen? Mit welcher Wirkung? Die Absichten der Verfasser einzuordnen klingt kritisch, prüft aber die Aussage nicht selbst: Auch ein Mensch mit Eigeninteresse kann recht haben, und ein Mensch ohne kann sich irren.","coreRule":"⚡ Streich die Gefühlswörter weg und schau, was als Behauptung übrig bleibt.","beleg":"Werkstück D.2.2 (Anwendung & Relevanz: In der Pseudomedizin; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wenn du die gefärbten Wörter probeweise durch neutrale ersetzt, siehst du, was tatsächlich behauptet wird, nämlich dass der Körper Stoffe ausscheidet und die Methode dabei hilft. Erst diese Behauptung lässt sich prüfen; die Wortwahl wirkt, ohne etwas zu belegen.","prueffrage":"Welcher Stoff soll den Körper verlassen, und woran würdest du merken, dass die Methode dabei hilft?","rueckmeldung":[{"option":0,"text":"Auf Widersprüche zu achten ist grundsätzlich gut. Hier gibt es aber keinen: Der Satz ist in sich stimmig und wirkt über seine Wortwahl. Die Prüfung findet also nichts, und der Satz bleibt unangetastet."},{"option":1,"text":"Wer verdient an der Methode, ist eine berechtigte Frage und ein Warnzeichen. Sie prüft aber die Aussage nicht selbst: Auch wer Eigeninteresse hat, kann recht haben. Der Satz selbst bleibt unbeleuchtet."},{"option":3,"text":"Ein Blick ins Wörterbuch klingt gründlich, bringt hier aber wenig. Die Wörter sind nicht unklar, sondern gefärbt: Sie wirken über ihren Beiklang, nicht über ihre Bedeutung. Die Wirkung bleibt damit ungeklärt."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4e08abae198f25cd"}},{"id":"qx-d1-027","clusterId":"D","werkstueckRef":"D.2.3","stufe":1,"question":"Eine Leserin sagt: „Eine der beiden Zeitungen muss lügen, denn eine Steuererhöhung kann nicht zugleich Investition und Enteignung sein.“ Was ist an diesem Schluss fehlerhaft?","scenario":"Dieselbe Steuererhöhung wird in einer Zeitung als „Investition in die Gemeinschaft“, in einer anderen als „Enteignung durch den Staat“ beschrieben. Beide Zeitungen nennen dieselben Zahlen.","options":["Er übersieht, dass beide Begriffe denselben Sachverhalt in einen anderen Deutungsrahmen setzen, ohne dass eine Zeitung Falsches behauptet.","Er übersieht, dass beide Zeitungen übertreiben können und die Wahrheit dann irgendwo in der Mitte zwischen den beiden Begriffen liegt.","Er übersieht, dass nur „Enteignung“ eine Wertung enthält, während „Investition in die Gemeinschaft“ denselben Sachverhalt sachlich beschreibt.","Er übersieht, dass zu einer Lüge die Absicht zu täuschen gehört, und diese Absicht lässt sich keiner der beiden Zeitungen nachweisen."],"correctIndex":0,"explanation":"Hier konkurrieren zwei Deutungsrahmen: der Gemeinschafts-Frame („Bürgerpflicht“, „Investition in die soziale Gemeinschaft“) und der Freiheits-Frame („Last“, „Enteignung durch den Staat“, Einschränkung der individuellen Freiheit). Je nachdem, welcher Frame dominiert, werden Steuererhöhungen als Investition oder als Diebstahl wahrgenommen. Der Unterschied liegt in Wortwahl und Blickwinkel, nicht in den Zahlen: Beide Zeitungen nennen dieselben Zahlen. Wer „Lüge“ ruft, verwechselt Rahmung mit Falschbehauptung. Beide Begriffe gehören zu je einem Deutungsrahmen. Besser ist die Frage: Welche anderen Frames gibt es, welche Aspekte hebt jeder hervor, welche lässt er außen vor, und zu welchen Lösungen würden wir kommen?","coreRule":"⚡ Wer den Rahmen setzt, entscheidet mit, was dieselben Zahlen bedeuten.","quote":"Wer den Frame kontrolliert, kontrolliert die Debatte.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück D.2.3 (Kontext & Tiefe: Beispiel Steuern)","status":"entwurf","kurz":"Beide Zeitungen nennen dieselben Zahlen und unterscheiden sich nur im Deutungsrahmen, den ihre Wörter aufspannen. Der Fehler liegt darin, einen anderen Blickwinkel mit einer Falschbehauptung zu verwechseln und deshalb „Lüge“ zu rufen.","prueffrage":"Was genau behaupten die beiden Zeitungen über die Steuererhöhung, wenn du Zahlen und Wertungen getrennt betrachtest?","rueckmeldung":[{"option":1,"text":"Dass Zeitungen übertreiben, kommt vor, nur gibt der Fall dafür nichts her. Hier stehen keine Tatsachenbehauptungen auf einer Skala, zwischen denen sich ein Mittelwert bilden ließe. Es sind zwei Deutungen derselben Zahlen."},{"option":2,"text":"„Enteignung“ klingt deutlich wertend, das stimmt. Aber auch „Investition in die Gemeinschaft“ ist eine Rahmung, die einen Aspekt betont und andere ausblendet. Beide Begriffe sind gleichermaßen Deutung, keiner ist neutrale Beschreibung."},{"option":3,"text":"Eine Lüge setzt tatsächlich Täuschungsabsicht voraus. Doch auch mit nachgewiesener Absicht läge hier keine Falschaussage vor, denn beide Zeitungen nennen dieselben Zahlen. Der Fehler liegt schon früher: Eine Rahmung wird für eine falsche Tatsachenbehauptung gehalten."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors we think with: The role of metaphor in reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lakoff, G. (2004): Don't Think of an Elephant! Know Your Values and Frame the Debate. White River Junction: Chelsea Green","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"294e6756ea94ebaa"}},{"id":"qx-d1-028","clusterId":"D","werkstueckRef":"D.2.3","stufe":2,"question":"Welche Erwartung ist am besten begründet, wenn die Klinik beide Entwürfe an Laien und an Ärzten testet?","scenario":"Eine Klinik will Patienten mit Lungenkrebs über zwei Behandlungswege aufklären: Operation oder Bestrahlung. Beide Entwürfe der Aufklärungsbroschüre geben dieselben Ergebnisse der Operation an. Entwurf 1 schreibt: „Die Ein-Monats-Überlebensrate liegt bei 90 Prozent.“ Entwurf 2 schreibt: „Im ersten Monat beträgt die Sterblichkeitsrate 10 Prozent.“ Ein Klinikleiter ist überzeugt: „Ärzte und Fachleute sind gegen solche Formulierungstricks gefeit. Nur medizinische Laien lassen sich davon beeinflussen.“","options":["Dass die Formulierung auch bei Ärzten die Entscheidung verschiebt, ist plausibel: Die Information ist gleich, doch der Gewinn- oder Verlustrahmen wirkt oft trotz Fachwissen.","Dass die Formulierung bei Laien wie Ärzten kaum etwas verschiebt, ist plausibel: Wer in beiden Entwürfen dieselben Zahlen liest, rechnet sie meist um und entscheidet dann gleich.","Dass sich nur Laien beeinflussen lassen, ist plausibel: Ärzte kennen die Behandlungsdaten genau und lassen sich von der Darstellung derselben Zahlen meist nicht lenken.","Dass die Formulierung Ärzte nur geringfügig beeinflusst, ist plausibel: Fachwissen dämpft die Wirkung des Rahmens deutlich, auch wenn es sie nicht ganz aufheben kann."],"correctIndex":0,"explanation":"Der Klinikleiter behauptet etwas, das sich prüfen lässt: Schützt Fachwissen vor dem Rahmen? Genau das wurde 1982 untersucht (McNeil u. a., New England Journal of Medicine): 238 Patienten mit anderen chronischen Erkrankungen, 491 Studierende und 424 Ärzte sollten sich vorstellen, an Lungenkrebs erkrankt zu sein, und zwischen Operation und Bestrahlung wählen. In allen drei Gruppen war die Operation beliebter, wenn die Ergebnisse als Überlebenswahrscheinlichkeit statt als Sterblichkeit angegeben waren. Nach der Darstellung bei Kahneman (2012) wählten 84 Prozent der Ärzte die Operation, wenn von einer Ein-Monats-Überlebensrate von 90 Prozent die Rede war. Hieß es dagegen, im ersten Monat betrage die Sterblichkeitsrate 10 Prozent, zogen 50 Prozent die Bestrahlung vor. Gleiche Information führt also je nach Rahmen zu unterschiedlichen Entscheidungen, und Fachwissen schützt nicht davor. Dass man die Zahlen ineinander umrechnen kann, klingt nach einem Schutz, ändert aber nichts, denn gemessen wurde die Entscheidung, nicht das Rechnen. Dass nur Laien betroffen seien, klingt nach dem Wert von Fachwissen, widerspricht aber den Ergebnissen: Auch Ärzte entschieden je nach Formulierung anders.","coreRule":"⚡ Dieselbe Zahl als Gewinn oder als Verlust formuliert lenkt auch Fachleute: Wer eine Aussage prüft, sollte sie in beiden Rahmen lesen.","beleg":"Werkstück D.2.3 (Einstiegsszene); Fn. gl-d-mcneil (McNeil u. a. 1982, NEJM 306(21), S. 1259–1262; Kahneman 2012, Kap. 34)","status":"entwurf","kurz":"Der Rahmen wirkte in der Studie bei Ärzten wie bei Laien: Gleiche Zahlen führten je nach Darstellung zu anderen Entscheidungen. Fachwissen klingt wie ein Schutz, doch gemessen wurde die Entscheidung, und die verschob sich auch bei Fachleuten.","prueffrage":"Worin unterscheiden sich die beiden Sätze, wenn die Zahlen dieselben sind, und was davon müsste ein Arzt anders lesen als ein Laie?","rueckmeldung":[{"option":1,"text":"Die Zahlen lassen sich ineinander umrechnen, und das klingt nach einem wirksamen Schutz. Gemessen wurde aber die Entscheidung, nicht das Rechnen, und die fiel auch bei Ärzten je nach Formulierung deutlich anders aus."},{"option":2,"text":"Daran stimmt: Ärzte kennen die Behandlungsdaten besser als Laien. Das schützt sie aber nicht vor dem Rahmen: Auch bei Ärzten fiel die Entscheidung je nach Formulierung anders aus, und das ist der Kern der Studie."},{"option":3,"text":"Dass auch Ärzte vom Rahmen beeinflusst werden, ist richtig. Dass Fachwissen die Wirkung deutlich dämpft, stützen die Ergebnisse nicht: Bei den Ärzten sprang die Wahl der Bestrahlung von 16 auf 50 Prozent, je nach Formulierung."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"McNeil, B. J.; Pauker, S. G.; Sox, H. C.; Tversky, A. (1982): On the elicitation of preferences for alternative therapies. NEJM 306(21), 1259–1262","oeffentlich":true,"doi":"10.1056/NEJM198205273062103","url":"https://pubmed.ncbi.nlm.nih.gov/7070445/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Kap. 34 „Frames und Wirklichkeit“, Abschnitt „Emotionales Framing“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"23ba2b0ac8812e45"}},{"id":"qx-d1-029","clusterId":"D","werkstueckRef":"D.2.3","stufe":3,"question":"Wie beurteilst du seine Aussage am besten?","scenario":"Ein Bekannter sagt: „Menschen denken in Frames, nicht in Fakten. Wer einmal in einem Rahmen steckt, den kannst du mit einer Richtigstellung nicht erreichen – das bringt nie etwas.“ Du hast den Verdacht, dass er die These übertreibt.","options":["Als zugespitzt: Rahmen lenken die Wahrnehmung stark, doch Richtigstellungen verringern Fehlvorstellungen meist, und nur selten verpuffen sie.","Als im Kern zutreffend: Das „nie“ ist zu hart, doch bei Menschen, die fest in einem Rahmen stecken, bleiben Richtigstellungen meist ohne Wirkung.","Als noch zu milde: Richtigstellungen erreichen Menschen in einem Rahmen kaum, und oft verfestigen sie die Fehlvorstellung sogar noch zusätzlich.","Als weit überzogen: Rahmen spielen kaum eine Rolle, sobald die Fakten klar vorliegen, und eine sachliche Richtigstellung überzeugt dann meistens."],"correctIndex":0,"explanation":"Die Aussage macht aus einer Tendenz ein Gesetz. Dass wir Informationen durch Deutungsrahmen ordnen und passende Fakten leichter aufnehmen als unpassende, ist plausibel; daraus folgt aber nicht, dass Fakten nie ankommen. Richtigstellungen verringern eine Fehlvorstellung meist, wenn auch oft nicht vollständig und nicht auf Dauer; dass sie ganz verpuffen oder sich ins Gegenteil verkehren, ist die Ausnahme. Wer die Aussage prüft, fragt daher nicht „Gibt es Rahmeneffekte?“, sondern „Wie stark und wie oft?“. Absolute Wörter wie „nie“ oder „immer“ sind dabei ein Warnsignal.","coreRule":"⚡ Rahmen lenken die Wahrnehmung, aber Fakten verlieren nicht automatisch dagegen: Wer „nie“ sagt, überzieht eine Tendenz zum Gesetz.","beleg":"Werkstück D.2.3 (Kontext & Tiefe: Lakoffs These und Einschränkung; Der Kipppunkt)","status":"entwurf","kurz":"Der Bekannte macht aus einer Tendenz ein Gesetz: Rahmen färben die Aufnahme von Fakten, doch Richtigstellungen verringern Fehlvorstellungen meist, wenn auch oft nicht ganz oder dauerhaft. Statt „Ob?“ lohnt die Frage „Wie stark und wie oft?“.","prueffrage":"Kennst du einen Fall, in dem jemand nach einer Richtigstellung seine Meinung tatsächlich geändert hat?","rueckmeldung":[{"option":1,"text":"Dass „nie“ zu hart ist, stimmt. Aber auch „meist ohne Wirkung“ ist überzogen: Richtigstellungen verringern Fehlvorstellungen in der Regel, wenn auch oft nicht vollständig und nicht auf Dauer."},{"option":2,"text":"Die Ahnung, dass Rahmen stark wirken, ist berechtigt, und eine Richtigstellung verfängt oft nur teilweise. Dass sie die Fehlvorstellung häufig noch verfestigt, ist aber die Ausnahme und nicht die Regel."},{"option":3,"text":"Richtig ist, dass Fakten durchaus ankommen. Falsch ist, Rahmen kaum noch Gewicht zu geben: Passende Informationen werden leichter aufgenommen, und eine Richtigstellung wirkt oft nur teilweise und nicht dauerhaft."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020, Auszug Teil 3 „The elusive backfire effects“ (Skeptical Science); vollständig: DOI 10.17910/b7.1182","oeffentlich":true,"url":"https://skepticalscience.com/debunking-handbook-2020-elusive-backfire-effects.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wood, T.; Porter, E. (2019): The Elusive Backfire Effect: Mass Attitudes' Steadfast Factual Adherence. Political Behavior 41(1), 135–163, DOI 10.1007/s11109-018-9443-y","oeffentlich":false},{"typ":"literatur","kurz":"Lakoff, G. (2004): Don't Think of an Elephant! Know Your Values and Frame the Debate. White River Junction: Chelsea Green","oeffentlich":false,"seite":"S. 17 (laut Belegregister)"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"1d0922fb31ecefd6"}},{"id":"qx-d1-030","clusterId":"D","werkstueckRef":"D.2.3","stufe":4,"question":"Wie gehst du am klügsten mit dieser Rahmung um?","scenario":"In einer Debatte über Drogenpolitik wird das Thema durchgehend als „Krieg gegen Drogen“ geführt. Die Schlussfolgerung scheint schon in der Wortwahl mitzulaufen: Wer von Krieg spricht, denkt an Gegner, Härte und Sieg. Du willst den Rahmen nicht unbemerkt übernehmen.","options":["Zuerst die Zahlen zu Konsum, Festnahmen und Haftstrafen klären, denn erst wenn die Fakten feststehen, lohnt es sich, über Begriffe zu reden.","Die Interessen derer prüfen, die vom „Krieg gegen Drogen“ sprechen, denn wer eine Rahmung setzt, verfolgt meist ein Ziel, das man kennen sollte.","Den Rahmen „Krieg“ benennen und andere Rahmen wie Gesundheit oder Bildung durchspielen, denn so zeigt sich, was er sichtbar macht und was er ausblendet.","Zuerst klären, was „Krieg“ und „Drogen“ in dieser Debatte genau bedeuten, denn unklare Begriffe lassen die Beteiligten aneinander vorbeireden."],"correctIndex":2,"explanation":"Ein Rahmen bestimmt, welche Aspekte eines Themas sichtbar werden und welche Lösungen naheliegen. Wer seinen Rahmen durchsetzt, hat oft schon gewonnen, bevor die erste Zahl genannt wird; wer ihn unbemerkt übernimmt, denkt innerhalb der Vorgaben anderer. Beim Rahmen „Krieg“ geht es dann um Gegner und Siege, nicht um Ursachen und Behandlung. Besser ist es, den Rahmen sichtbar zu machen und Alternativen zu prüfen: Was ändert sich, wenn das Problem als Gesundheitsproblem oder als Bildungsaufgabe betrachtet wird? Zu welchen anderen Lösungen käme man dann? Rahmungen sind dabei nicht per se manipulativ, denn ohne sie können wir die Welt gar nicht ordnen. Zum Problem werden sie, wenn wir den Rahmen nicht bemerken, in dem wir denken.","coreRule":"⚡ Frag nicht nur, ob die Fakten stimmen, sondern in welchem Rahmen sie dir gezeigt werden.","beleg":"Werkstück D.2.3 (Das Anti-Denkmuster; Das Adaptive Talent)","status":"entwurf","quote":"Welche anderen, alternativen Frames gibt es?","quoteLabel":"Prüffrage","kurz":"Der Rahmen „Krieg“ legt Gegner, Härte und Sieg nahe und blendet Ursachen und Behandlung aus. Erst wenn du ihn benennst und andere Rahmen wie Gesundheit oder Bildung durchspielst, siehst du, was er zeigt und was er verdeckt.","prueffrage":"Welche Maßnahmen gegen Drogenprobleme fallen dir ein, und welche davon passen zum Wort „Krieg“?","rueckmeldung":[{"option":0,"text":"Zahlen sind wichtig, und Sorgfalt klingt vernünftig. Doch dieselben Zahlen lesen sich im Bild des Krieges anders als im Bild einer Gesundheitsfrage. Die Faktenklärung allein macht den Rahmen nicht sichtbar."},{"option":1,"text":"Die Interessen der Sprecher zu kennen kann durchaus helfen. Es sagt aber nichts darüber, was das Bild vom „Krieg“ sichtbar macht und was es ausblendet. Dafür muss der Rahmen selbst untersucht werden."},{"option":3,"text":"Begriffe zu klären wirkt gründlich und ist oft sinnvoll. Hier gibt es aber kein Missverständnis: Alle verstehen, was „Krieg“ meint. Das Problem ist die Wirkung des Bildes, nicht seine Unschärfe."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors we think with: The role of metaphor in reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lakoff, G.; Johnson, M. (1980): Metaphors We Live By. Chicago: University of Chicago Press; dt. Leben in Metaphern, 9. Aufl. Heidelberg: Carl-Auer 2018","oeffentlich":false,"seite":"Kap. 1, S. 11–13 (laut Landkarte-Fußnote gl-d-lakoffjohnson)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8b645c5a353df7fe"}},{"id":"qx-d1-031","clusterId":"D","werkstueckRef":"D.2.4","stufe":1,"question":"Was ist an diesem Argument der Kernfehler?","scenario":"Dein Nachbar warnt: „Erst Tempo 30 vor der Schule, dann in der ganzen Straße, dann ein Autoverbot in der Innenstadt – am Ende gehen wir alle zu Fuß!“ Belege für die einzelnen Schritte nennt er nicht.","options":["Er malt ein Schreckensbild aus, um mit Angst statt mit Gründen zu überzeugen.","Er verallgemeinert vorschnell von einer einzelnen Schule auf die Stadt.","Er übergeht die Frage, ob Tempo 30 vor der Schule für sich sinnvoll ist.","Er stellt die einzelnen Folgen als zwangsläufig dar, ohne sie zu belegen."],"correctIndex":3,"explanation":"Das ist ein Dammbruch-Fehlschluss (Slippery Slope): Eine kleine erste Maßnahme soll unweigerlich in einer Katastrophe enden. Der Fehler liegt in der behaupteten Zwangsläufigkeit. Es wird so getan, als gäbe es zwischen Tempo 30 vor der Schule und dem Autoverbot keine Haltepunkte, etwa Gesetze, Gerichte, öffentliche Proteste oder den gesunden Menschenverstand. Eine Warnung vor einer wahrscheinlichen, belegten Folge wäre dagegen kein Fehlschluss. Hier ist die Kette nur behauptet, kein einziger Übergang ist belegt. Eine Warnung vor Folgen ist nicht per se ein Fehlschluss: Entscheidend ist, ob Wahrscheinlichkeit und Gewicht der befürchteten Folge begründet sind (vgl. Hahn/Oaksford 2006).","coreRule":"⚡ Prüfe jeden Pfeil der Kette einzeln, nicht nur das Schreckensbild am Ende.","beleg":"Werkstück D.2.4 (Kernidee; Kontext & Tiefe; Fußnote gl-d-hahn: Hahn/Oaksford 2006)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Der Nachbar behauptet, jeder Schritt führe zwangsläufig zum nächsten, belegt aber keinen einzigen Übergang. Der naheliegende Fehler ist, die Warnung vor einer Katastrophe schon für einen Beleg zu halten, obwohl es Haltepunkte geben kann.","prueffrage":"Was müsste zwischen Tempo 30 vor der Schule und einem Autoverbot in der Innenstadt alles geschehen und beschlossen werden?","rueckmeldung":[{"option":0,"text":"Das Bild vom Zu-Fuß-Gehen wirkt tatsächlich drastisch. Eine Warnung vor Folgen ist aber nicht schon deshalb ein Fehler, weil sie Angst macht; entscheidend ist, ob die Kette begründet ist, und genau daran fehlt es hier."},{"option":1,"text":"Verallgemeinern liegt nahe, weil es um Schule, Straße und Innenstadt geht. Der Nachbar schließt aber nicht von einem Fall auf viele, sondern behauptet eine Abfolge von Schritten, die einander auslösen sollen, ohne dass einer belegt wäre."},{"option":2,"text":"Ob Tempo 30 vor der Schule für sich sinnvoll ist, hat der Nachbar tatsächlich nicht geklärt. Das ist aber nicht der Kern: Selbst bei offener Nutzenfrage bleibt das Problem, dass die behauptete Zwangsläufigkeit der Folgen ungestützt ist."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt Slippery Slope). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"6dbcf9aeef294e4e"}},{"id":"qx-d1-032","clusterId":"D","werkstueckRef":"D.2.4","stufe":2,"question":"Vier Personen warnen vor einer Entwicklung. Welche Warnung ist ein stichhaltiges Kausalargument und kein Dammbruch-Fehlschluss?","options":["„Wenn wir Tempo 30 in der Innenstadt einführen, ist es wahrscheinlich, dass bald das Autoverbot folgt und der Staat am Ende bestimmt, wohin wir reisen dürfen.“","„Wenn du bei Glatteis 100 km/h fährst, ist die Wahrscheinlichkeit hoch, dass du auf dem glatten Untergrund die Kontrolle verlierst und einen schweren Unfall baust.“","„Wenn wir Schulnoten abschaffen, lässt der Ehrgeiz zwangsläufig nach, dann sinkt das Niveau, und am Ende geht die ganze Wirtschaft zugrunde.“","„Wenn wir KI-Hilfe bei Hausaufgaben erlauben, ist es wahrscheinlich, dass Schüler bald nicht mehr selbst denken und in einer Generation das Lesen verlernen.“"],"correctIndex":1,"explanation":"Die Glatteis-Warnung ist eine Wahrscheinlichkeitsaussage: Sie basiert auf Physik und Statistik, und die Kette ist probabilistisch und belegt. Die Warnung behauptet nur ein erhöhtes Risiko, keine Gewissheit. Sie übergehen auch alle Bremsen, die in der Realität dazwischenstehen, etwa Gerichte, Verfassung, Gewaltenteilung, öffentlichen Protest oder die menschliche Vernunft. Entscheidend ist also nicht die Wenn-dann-Form, sondern ob eine Wahrscheinlichkeit belegt oder eine Zwangsläufigkeit nur behauptet wird.","coreRule":"⚡ Eine belegte Wahrscheinlichkeit ist eine Warnung – eine behauptete Zwangsläufigkeit ist Panikmache.","beleg":"Werkstück D.2.4 (Kontext & Tiefe: legitimes Kausalargument vs. Fehlschluss; Anwendung & Relevanz)","status":"entwurf","scenario":"In einer Diskussionsrunde fallen vier Wenn-dann-Warnungen. Du sollst entscheiden, welche davon ernst zu nehmen ist und welche nur Angst erzeugt.","kurz":"Die Glatteis-Warnung behauptet nur ein erhöhtes Risiko und stützt sich auf Physik und Statistik. Der Fehler der anderen: Schritt an Schritt bis zur Katastrophe, ohne dass ein einziger Übergang belegt ist.","prueffrage":"Welche der vier Folgen ließe sich an Beobachtungen oder Unfallzahlen überprüfen?","rueckmeldung":[{"option":0,"text":"Dass über Tempo 30 gestritten wird, macht die Warnung nicht stichhaltig. Von der Geschwindigkeitsregel bis zur staatlichen Reisekontrolle ist kein Übergang belegt, und Gerichte, Verfassung und Protest stehen dazwischen."},{"option":2,"text":"Bedenken zur Notenabschaffung können berechtigt sein, doch „zwangsläufig“ ist nur behauptet. Vom Ehrgeiz über das Niveau bis zum Ruin der Wirtschaft fehlt für jeden Schritt der Beleg, und die Folge steht in keinem Verhältnis zum Anfang."},{"option":3,"text":"Das „wahrscheinlich“ klingt vorsichtig, hat aber keine Grundlage. Ob KI-Hilfe bei Hausaufgaben ein Thema ist, steht nicht in Frage, doch dass dadurch in einer Generation das Lesen verlernt wird, ist unbelegt. Lehrkräfte, Regeln und Unterricht wirken als Bremsen dazwischen."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt Slippery Slope). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ad0f9b8a6a00fc4d"}},{"id":"qx-d1-033","clusterId":"D","werkstueckRef":"D.2.4","stufe":3,"question":"Woran erkennst du, dass aus einer berechtigten Warnung ein Fehlschluss geworden ist?","scenario":"In einer Debatte über neue Technik sagt jemand zuerst: „Ich befürchte, das könnte das Risiko für Missbrauch erhöhen.“ Später heißt es: „Das wird unweigerlich zu totaler Überwachung führen!“","options":["Daran, dass die zweite Aussage mit Ausrufezeichen und zugespitzten Worten auftritt, denn damit tritt die bloße Erregung an die Stelle sachlicher Gründe.","Daran, dass aus „könnte erhöhen“ ein „wird unweigerlich zu totaler Überwachung führen“ wird, denn damit ersetzt Zwangsläufigkeit die Wahrscheinlichkeit.","Daran, dass aus „Missbrauch“ die viel schwerere „totale Überwachung“ wird, denn eine Warnung kippt, sobald die befürchtete Folge viel zu drastisch ausfällt.","Daran, dass hier überhaupt von künftigen Folgen der Technik die Rede ist, denn Warnungen vor etwas, das erst kommen könnte, lassen sich kaum prüfen."],"correctIndex":1,"explanation":"Eine Warnung benennt ein Risiko: Etwas könnte wahrscheinlicher werden, und das lässt sich mit Belegen prüfen. Kippt sie in „wird unweigerlich“, wird eine Möglichkeit als Gewissheit ausgegeben, obwohl Bremsklötze wie Gesetze, Gerichte oder öffentliche Proteste die Kette unterbrechen können. Entscheidend ist der Übergang von Wahrscheinlichkeit zu Zwangsläufigkeit.","coreRule":"⚡ „Könnte erhöhen“ ist eine Warnung, „wird unweigerlich“ ein Alarmruf ohne Beleg.","beleg":"Werkstück D.2.4 (Der Kipppunkt); Fn. gl-d-hahn (Hahn/Oaksford 2006, Informal Logic 26(1), S. 6–7)","status":"entwurf","kurz":"Aus „könnte erhöhen“ wird „wird unweigerlich“: Eine prüfbare Möglichkeit gilt plötzlich als Gewissheit, obwohl Gesetze, Gerichte oder Proteste die Kette unterbrechen können. Genau dieser Sprung macht aus der Warnung einen Fehlschluss.","prueffrage":"Was könnte zwischen der neuen Technik und totaler Überwachung noch dazwischenkommen, und lässt die zweite Aussage dafür Raum?","rueckmeldung":[{"option":0,"text":"Die zweite Aussage klingt tatsächlich schärfer. Ausrufezeichen und starke Worte machen eine Aussage aber nicht falsch; auch eine begründete Warnung kann laut sein. Es kommt darauf an, was behauptet wird, nicht wie nachdrücklich."},{"option":2,"text":"Dass die befürchtete Folge schwerer wiegt, ist ein Grund zur Nachfrage. Auch vor drastischen Folgen darf man aber berechtigt warnen. Der Fehler liegt woanders: darin, dass aus einem Risiko eine Gewissheit wird."},{"option":3,"text":"Künftige Folgen sind unsicher, aber nicht unprüfbar: Ein Risiko lässt sich mit Belegen abwägen, etwa mit Erfahrungen aus ähnlichen Fällen. Unsicherheit spricht eher gegen „unweigerlich“ als gegen jede Warnung."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt Slippery Slope). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"b511f8c98e56a12f"}},{"id":"qx-d1-034","clusterId":"D","werkstueckRef":"D.2.4","stufe":4,"question":"Wie solltest du die Aussage der Kollegin beurteilen?","scenario":"Eine Kollegin meint: „Ein Dammbruch-Argument ist immer ein Fehlschluss. Die Form ‚A führt zu B, B zu C, C zu Z‘ taugt nichts.“ Du erinnerst dich an zwei Fälle: Wer bei Glatteis mit 100 km/h fährt, riskiert einen schweren Unfall. Wer behauptet, eine um eine Stunde verlängerte Sperrstunde führe „unweigerlich“ in die „24-Stunden-Anarchie“, nennt dagegen keinerlei Belege.","options":["Sie ist im Recht, weil die Wahrscheinlichkeit mit jedem Zwischenschritt sinkt, sodass auch Ketten wie Glatteis, Kontrollverlust und Unfall kaum tragfähig sind.","Sie ist zu pauschal, weil ein solches Argument umso stärker wird, je wahrscheinlicher und gewichtiger die befürchtete Folge ist, wie der Unfall bei Glatteis zeigt.","Sie ist zu pauschal, weil ein solches Argument schon dann trägt, wenn die befürchtete Folge schwer genug wiegt, wie der Unfall bei Glatteis zeigt; dann geht Vorsicht vor.","Sie ist im Recht, weil die Sperrstunden-Rede mit ihrem „unweigerlich“ zeigt, wie solche Ketten gebaut sind: Sie leben von Übertreibung statt von Belegen."],"correctIndex":1,"explanation":"Die Form „A führt zu B, B zu C“ ist an sich weder gut noch schlecht, entscheidend ist der Inhalt. Die Warnung vor dem Glatteis-Unfall stützt sich auf Physik und Statistik: Die Folge ist wahrscheinlich und schwerwiegend, also trägt das Argument. Die Sperrstunden-Rede behauptet dagegen Zwangsläufigkeit ohne Beleg für einen einzigen Übergang und ignoriert alle Bremsen im System. Auch die Argumentationsforschung (Hahn und Oaksford) kommt zu diesem Ergebnis: Ein Dammbruch-Argument ist umso stärker, je realer die Chance der befürchteten Folge ist, und es lassen sich ausdrücklich „perfectly acceptable examples“ bilden. Klassische Fehlschlüsse sind Argumentformen, die je nach Inhalt unterschiedlich stark sein können. Der Fehler liegt in der behaupteten Zwangsläufigkeit: Eine Möglichkeit wird als Gewissheit dargestellt, und für die Übergänge fehlen die Belege. Er liegt nicht schon in der Wenn-dann-Form. Ebenso falsch wäre der Gegenschluss, jede Folgenwarnung sei gültig: Prüfe jeden Übergang einzeln. Dass die Wahrscheinlichkeit mit jedem Zwischenschritt sinkt, stimmt und klingt nach einem Argument gegen alle Ketten, macht aber kurze und belegte Ketten wie die Glatteis-Warnung nicht ungültig. Und dass ein schweres Gewicht der Folge genügte, klingt nach Vorsicht, doch auch die Anarchie-Warnung ist schwer genug und bleibt ohne Beleg für die Übergänge; erst Gewicht und Wahrscheinlichkeit zusammen tragen.","coreRule":"⚡ Ob eine Folgenwarnung trägt, entscheidet ihr Inhalt (Wahrscheinlichkeit, Gewicht, Belege für jeden Übergang), nicht ihre Wenn-dann-Form.","beleg":"Werkstück D.2.4 (Kernidee; Red Flags); Fn. gl-d-hahn (Hahn/Oaksford 2006, Informal Logic 26(1), S. 6–7; 2007, Psychological Review 114(3), S. 704–732)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Ein Dammbruch-Argument ist umso stärker, je wahrscheinlicher und gewichtiger die befürchtete Folge ist. Der Fehler liegt nicht in der Wenn-dann-Form, sondern in unbelegter Zwangsläufigkeit, wie bei der Sperrstunde, nicht beim Glatteis.","prueffrage":"Haben die Glatteis-Warnung und die Sperrstunden-Rede dieselbe Form, und sind sie gleich gut begründet?","rueckmeldung":[{"option":0,"text":"Mit jedem Zwischenschritt sinkt die Wahrscheinlichkeit der ganzen Kette, das stimmt. Daraus folgt aber nicht, dass jede Kette kaum trägt: Kurze, belegte Übergänge wie bei der Glatteis-Warnung bleiben stark."},{"option":2,"text":"Dass die Aussage zu pauschal ist, trifft zu. Das Gewicht der Folge allein genügt aber nicht: Auch die Anarchie-Warnung wiegt schwer und bleibt ohne Beleg für die Übergänge. Erst Gewicht und Wahrscheinlichkeit zusammen tragen."},{"option":3,"text":"Die Sperrstunden-Rede ist tatsächlich schwach, weil sie Zwangsläufigkeit ohne Beleg behauptet. Aus einem schlechten Beispiel folgt aber nichts über die ganze Form: Die Glatteis-Warnung zeigt, dass solche Ketten tragen können."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hahn, U.; Oaksford, M. (2007): The Rationality of Informal Argumentation: A Bayesian Approach to Reasoning Fallacies. Psychological Review 114(3), 704–732","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"79a3fe4f96b6f0e1"}},{"id":"qx-d1-035","clusterId":"D","werkstueckRef":"D.2.5","stufe":2,"question":"Was spricht am stärksten gegen die Behauptung, solche Wendungen seien bloßer Sprachschmuck?","scenario":"Zwei Kollegen sprechen über eine Teamsitzung. Die eine sagt: „Er hat meine Position angegriffen, ich habe mich gut verteidigt, und am Ende habe ich die Debatte gewonnen.“ Der andere widerspricht: „Das ist doch nur Wortwahl. Sprache ist Schmuck, am Denken ändert sich nichts, wenn man ein anderes Wort benutzt.“","options":["Solche Wendungen sind so alltäglich, dass sie das Denken über Argumentieren unbemerkt als Kampf prägen, ohne dass „angreifen“ oder „verteidigen“ als Bilder auffallen.","Solche Wendungen benutzen sehr viele Menschen ganz selbstverständlich, und was so verbreitet ist und ständig gesagt wird, kann kaum bloßer Zierrat ohne Wirkung sein.","Solche Wendungen legen fest, was wir denken können, denn wer für Gespräche nur Wörter wie „angreifen“ und „gewinnen“ hat, kann eine Debatte kaum anders als einen Kampf sehen.","Solche Wendungen lassen sich nicht ohne Verlust tauschen, denn „ich habe die Debatte gewonnen“ sagt etwas anderes als „ich habe überzeugt“, also tragen sie eigenen Inhalt."],"correctIndex":0,"explanation":"Wenn wir eine Position „verteidigen“, ein Argument „angreifen“ oder eine Debatte „gewinnen“, übertragen wir die Struktur eines Kampfes auf ein Gespräch. Solche Metaphern sind in der Alltagssprache so selbstverständlich, dass wir sie meist nicht mehr als Bilder bemerken und oft gar keine wörtliche Alternative zur Hand haben. Gerade deshalb sind sie kein austauschbarer Schmuck: Sie prägen im Hintergrund mit, was wir an einer Sache wahrnehmen (Gegner, Sieg, Niederlage). Dass Metaphern das Urteil lenken können, deutet ein Experiment von 2011 an: Derselbe Bericht über steigende Kriminalität führte zu deutlich mehr Zustimmung zu repressiven Maßnahmen, wenn Kriminalität als wildes Tier beschrieben wurde, als wenn sie als Virus beschrieben wurde (74 % gegenüber 56 %), obwohl die Fakten identisch waren und fast niemand das Bild als Ursache nannte. Dieses Experiment hatte allerdings keine Vergleichsgruppe ohne Metapher, und eine Wiederholung der Nachfolgestudie von 2013 fand 2014 keinen Metaphern-Effekt; die Größe und Robustheit des Effekts sind also umstritten. Die Wirkung setzt nicht voraus, dass die Metapher bewusst bemerkt wird: In der Nachfolgestudie von 2013 zeigte sich der Effekt sogar bei Personen, die sich an das Bild nicht mehr erinnerten.","coreRule":"⚡ Wir benutzen die Bilder der Sprache, und sie benutzen unser Denken.","beleg":"Werkstück D.2.5 (Kontext & Tiefe); Fn. gl-d-lakoffjohnson (Lakoff/Johnson 1980; dt. Heidelberg: Carl-Auer, Kap. 1, S. 11–13, hier S. 12)","status":"entwurf","kurz":"Solche Bilder sind so selbstverständlich, dass wir sie kaum als Bilder bemerken und oft keine wörtliche Alternative haben. Genau deshalb können sie im Hintergrund mitprägen, was wir an einem Gespräch sehen, etwa Gegner und Sieg, und sind kein bloßer Schmuck.","prueffrage":"Welches andere Wort würdest du für „sich verteidigen“ in diesem Gespräch einsetzen, und fällt dir überhaupt eins ein?","rueckmeldung":[{"option":1,"text":"Dass etwas häufig vorkommt, zeigt noch keine Wirkung, denn auch harmlose Floskeln sind verbreitet. Entscheidend ist, dass man das Bild nicht mehr bemerkt und kaum Alternativen hat. Dann kann es im Hintergrund mitprägen, was man wahrnimmt."},{"option":2,"text":"Hier ist die Wirkung zu stark gezeichnet. Metaphern können das Urteil lenken und eine Sicht nahelegen, sie legen aber nicht fest, was überhaupt denkbar ist. Zudem ist die Größe des Effekts umstritten."},{"option":3,"text":"„Gewonnen“ und „überzeugt“ meinen tatsächlich Verschiedenes. Das zeigt aber nur, dass die Wörter nicht gleichwertig sind, nicht dass das Bild unbemerkt mitprägt. Der Kern ist die selbstverständliche, kaum bemerkte Alltäglichkeit der Metapher."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lakoff, G.; Johnson, M. (1980): Metaphors We Live By. Chicago: University of Chicago Press (dt. Leben in Metaphern, 9. Aufl. Heidelberg: Carl-Auer 2018), Kap. 1","oeffentlich":false},{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"doi","kurz":"Steen, G. J.; Reijnierse, W. G.; Burgers, C. (2014): When Do Natural Language Metaphors Influence Reasoning? A Follow-Up Study to Thibodeau and Boroditsky (2013). PLoS ONE 9(12), e113536","oeffentlich":true,"doi":"10.1371/journal.pone.0113536","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b65423f206270ce4"}},{"id":"qx-d1-036","clusterId":"D","werkstueckRef":"D.2.5","stufe":4,"question":"Ein Kollege schickt dir eine Schlagzeile: „Studie belegt: Ein einziges Wort im ersten Satz verändert politische Urteile um fast 20 Prozentpunkte.“ Du recherchierst: Das Experiment hatte keine Vergleichsgruppe ohne Metapher. Eine unabhängige Wiederholung einer späteren Studie derselben Forschenden fand keinen Metaphern-Effekt; schon das Lesen über Kriminalität verschob die Antworten in Richtung Polizei und Strafe, gleich welches Bild der Text benutzte. Eine Auswertung von 91 Studien fand metaphorische Rahmen wirksam, aber nur schwach. Wie sicher darfst du die Schlagzeile nehmen?","options":["Die Behauptung ist weitgehend gestützt: Die Auswertung von 91 Studien fand den Effekt wirksam, und die gescheiterte Wiederholung betrifft nur eine einzelne spätere Studie derselben Forschenden.","Die Behauptung ist weitgehend widerlegt: Die unabhängige Wiederholung fand keinen Metaphern-Effekt, und die Auswertung von 91 Studien zeigt nur eine schwache Wirkung, die man vernachlässigen darf.","Die Grundrichtung ist plausibel gestützt, die genannte Größe aber unsicher: Es fehlt eine Vergleichsgruppe ohne Metapher, und die Befunde streuen zwischen stark und kaum vorhanden.","Die Behauptung ist im Kern bestätigt: Auch die Wiederholung fand, dass der gelesene Text die Antworten verschiebt, also ändert schon ein einzelnes Wort das politische Urteil deutlich."],"correctIndex":2,"explanation":"Ein Befund wird nicht dadurch sicher, dass er eine eindrucksvolle Zahl liefert. Hier fehlt in der Ausgangsstudie die Vergleichsgruppe ohne Metapher: Man kann nicht erkennen, ob das Bild etwas bewirkt oder ob schon das Lesen über Kriminalität die Antworten in Richtung Polizei und Strafe verschiebt. Genau das zeigte eine unabhängige Wiederholung der Folgestudie (Steen, Reijnierse und Burgers 2014): kein Metaphern-Effekt; schon das Lesen über Kriminalität verschob die Antworten in Richtung Polizei und Strafe, gleich welches Bild der Text benutzte. Eine Auswertung von 91 Studien (Brugman u. a. 2019) fand metaphorische Rahmen dagegen wirksam, aber nur schwach. Angemessen ist ein abgestuftes Urteil: Richtung plausibel, Größe und Robustheit offen.","coreRule":"⚡ Urteile über Studienbefunde abgestuft: Eine spektakuläre Zahl ohne Vergleichsgruppe und mit uneinheitlicher Replikation verdient „plausible Richtung, unsichere Größe“, weder blinden Glauben noch Totalverwurf.","beleg":"Werkstück D.2.5 (Hinweis zur Beleglage); Fn. gl-d-thibodeau (Thibodeau/Boroditsky 2011, 2013; Steen u. a. 2014, PLOS ONE 9(12), e113536; Brugman u. a. 2019, Language and Cognition 11(1), S. 41–65)","status":"entwurf","scenario":"","kurz":"Eine eindrucksvolle Zahl macht einen Befund nicht sicher: Ohne Vergleichsgruppe ist offen, ob das Bild wirkt oder schon das Thema, und die Befunde zeigen höchstens eine schwache Wirkung. Die Richtung ist plausibel, die Größe offen.","prueffrage":"Was fanden die Wiederholung und die Auswertung der 91 Studien jeweils, gemessen an den fast 20 Prozentpunkten der Schlagzeile?","rueckmeldung":[{"option":0,"text":"Die Auswertung von 91 Studien fand tatsächlich eine Wirkung, und eine einzelne Wiederholung widerlegt nicht alles. Sie fand aber nur eine schwache Wirkung und stützt die fast 20 Prozentpunkte der Schlagzeile nicht."},{"option":1,"text":"Die gescheiterte Wiederholung wiegt schwer, doch sie betrifft nur eine einzelne Studie. Die Auswertung fand metaphorische Rahmen wirksam, wenn auch schwach, und eine schwache Wirkung ist keine, die man vernachlässigen oder als widerlegt abtun darf."},{"option":3,"text":"Dass schon der gelesene Text die Antworten verschiebt, stimmt, spricht aber gegen die Schlagzeile: Es zeigt die Wirkung des Themas, gleich welches Bild benutzt wurde. Der Metaphern-Effekt selbst blieb in der Wiederholung aus."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Steen, G. J.; Reijnierse, W. G.; Burgers, C. (2014): When Do Natural Language Metaphors Influence Reasoning? A Follow-Up Study to Thibodeau and Boroditsky (2013). PLoS ONE 9(12), e113536","oeffentlich":true,"doi":"10.1371/journal.pone.0113536","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brugman, B. C.; Burgers, C.; Vis, B. (2019): Metaphorical framing in political discourse through words vs. concepts: a meta-analysis. Language and Cognition 11(1), 41–65 (Open Access)","oeffentlich":true,"doi":"10.1017/langcog.2019.5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3cb54812fb7b0e1d"}},{"id":"qx-d1-037","clusterId":"D","werkstueckRef":"D.2.5","stufe":2,"question":"Was sollte das Kampagnenteam aus diesen Befunden für seinen Slogan ableiten?","scenario":"Eine Gesundheitskampagne soll Menschen ohne Krebserkrankung zur Krebsvorsorge bewegen. Geplant ist der Slogan „Gemeinsam den Krebs bekämpfen!“; die Verantwortlichen sind überzeugt, das Kampfbild wecke Dringlichkeit. In vier Online-Studien mit Versuchspersonen ohne Krebserkrankung ließ die Rede vom „Kampf“ gegen den Krebs die Behandlung schwieriger erscheinen und verstärkte die Haltung, gegen Krebs könne man ohnehin wenig tun; die Bereitschaft, zum Arzt zu gehen, stieg nicht.","options":["Das Team kann den Slogan behalten, weil Online-Studien eine echte Kampagne kaum abbilden und die Dringlichkeit im Alltag anders wirken kann.","Das Team sollte auf bildhafte Sprache ganz verzichten, weil die Studien zeigen, dass solche Bilder bei Gesundheitsthemen eher schaden.","Das Team sollte die erhoffte Dringlichkeit nicht voraussetzen und den Slogan vorher prüfen, weil die Studien eher Fatalismus fanden.","Das Team kann den Slogan behalten, weil mehr Fatalismus in den Studien noch nicht heißt, dass weniger Menschen zur Vorsorge gehen."],"correctIndex":2,"explanation":"Die Hoffnung, ein Kampfbild wecke Dringlichkeit, ist eine plausible, aber ungeprüfte Annahme, und gut gemeinte Bilder haben oft Nebenwirkungen. In vier Online-Studien (Hauser und Schwarz 2020) ließ die Rede vom „Kampf“ gegen den Krebs die Behandlung schwieriger erscheinen und verstärkte den Fatalismus („gegen Krebs kann man ohnehin wenig tun“); die Bereitschaft, zum Arzt zu gehen, stieg nicht. Wer ein Bild für wirksam hält, sollte also messen, was es tatsächlich bewirkt, statt es vorauszusetzen; genau das muss das Team vor dem Start tun. Vorbehalt: Untersucht wurden Personen ohne Krebserkrankung; Aussagen über Betroffene lassen sich daraus nicht ableiten.","coreRule":"⚡ Auch gut gemeinte Bilder wie der „Kampf“ haben Nebenwirkungen darauf, was Menschen für möglich halten. Ob ein Bild wirkt wie erhofft, muss man prüfen, nicht annehmen.","beleg":"Werkstück D.2.5 (Anwendung & Relevanz: Gesundheitspolitik); Fn. gl-d-kampfmetapher (Hauser/Schwarz 2020, Health Communication 35(13), S. 1698–1704)","status":"entwurf","kurz":"Die Dringlichkeit, die das Kampfbild wecken soll, ist nur eine plausible Annahme, und die Studien fanden eher Fatalismus statt mehr Arztbereitschaft. Wer ein Bild für wirksam hält, sollte seine Wirkung vor dem Start prüfen, statt sie vorauszusetzen.","prueffrage":"Woran würdest du erkennen, dass der Slogan bei der Zielgruppe wirklich zum Handeln führt, und nicht nur gut klingt?","rueckmeldung":[{"option":0,"text":"Dass Online-Studien keine echte Kampagne abbilden, stimmt. Daraus folgt aber nicht, dass der Slogan unbedenklich ist: Die einzigen vorliegenden Befunde sprechen gegen die Dringlichkeits-Annahme, und im Alltag wäre das erst zu prüfen."},{"option":1,"text":"Dass bildhafte Sprache Nebenwirkungen haben kann, zeigt sich hier tatsächlich. Untersucht wurde aber nur das Kampfbild beim Thema Krebs; auf alle Bilder und Gesundheitsthemen lässt sich das nicht ausdehnen."},{"option":3,"text":"Mehr Fatalismus ist tatsächlich nicht dasselbe wie weniger Vorsorge. Nur stieg in den Studien auch die Bereitschaft zum Arztbesuch nicht; der erhoffte Nutzen ist also unbelegt, und der Slogan bliebe ungeprüft im Einsatz."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hauser, D. J.; Schwarz, N. (2020): The War on Prevention II: Battle Metaphors Undermine Cancer Treatment and Prevention and Do Not Increase Vigilance. Health Communication 35(13), 1698–1704 (Verlagsfassung, USC Dornsife)","oeffentlich":true,"doi":"10.1080/10410236.2019.1663465","url":"https://dornsife.usc.edu/norbert-schwarz/wp-content/uploads/sites/231/2023/12/20_HC_Hauser_Schwarz_War_on_cancer_II.pdf","seite":"1698","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"30b3a799ba64a48e"}},{"id":"qx-d1-038","clusterId":"D","werkstueckRef":"D.2.5","stufe":3,"question":"Was ist an der Forderung der Leserin am ehesten das Problem?","scenario":"Eine Zeitung berichtet über Migration. In jedem Artikel kommen „Flut“, „Welle“ und „Dämme“ vor, die genannten Zahlen sind korrekt. In Artikeln anderer Zeitungen über dieselben Zahlen ist von „Wanderungsbewegungen“, „Arbeitskräften“ oder einzelnen Lebensläufen die Rede. Eine Leserin sagt: „Naturbilder für Menschen sind grundsätzlich unzulässig, jede Zeitung müsste sie verbieten.“","options":["Sie verlangt ein Verbot von Bildern, obwohl jede Sprache über Migration irgendein Bild braucht; problematisch wird nur ein einziges Bild ohne Alternativen.","Sie übersieht, dass korrekte Zahlen im Text den Einfluss eines Bildes vollständig aufheben; ein Verbot ist daher überflüssig.","Sie übersieht, dass Leser ein lenkendes Bild sofort bemerken; deshalb braucht es keinen Schutz davor.","Sie verkennt, dass Naturbilder für Menschen nur irreführen, wenn die berichteten Zahlen falsch sind."],"correctIndex":0,"explanation":"Metaphern sind ein unvermeidbares Werkzeug des Denkens: Abstraktes lässt sich ohne Bilder kaum beschreiben, also kann es nicht darum gehen, Bilder zu verbieten. Problematisch wird ein Bild, wenn es zur einzigen Linse wird. Eine Naturkatastrophen-Metapher lässt Menschen unbemerkt als unpersönliche Naturgewalt erscheinen, gegen die man „Dämme“ baut, statt zu verhandeln, und Alternativen wie Wanderungsbewegung, Lebensläufe oder Arbeitsmarktfrage verschwinden aus dem Text. Dass Bilder auch bei korrekten Zahlen lenken, zeigte ein Experiment von Thibodeau und Boroditsky (2011): Bei identischer Kriminalstatistik unterschied sich die Zustimmung zu repressiven Maßnahmen je nach Tier- oder Virus-Bild um rund 18 Prozentpunkte, und fast niemand nannte die Metapher als Einflussfaktor. (Die genaue Größe und Robustheit des Effekts ist umstritten; seine Grundrichtung gilt aber als durch mehrere Studien gestützt.) Zu prüfen ist deshalb, ob es Alternativen zum Bild gibt und ob es offengelegt wird.","coreRule":"⚡ Nicht das Bild ist das Problem, sondern ein Bild ohne Alternative.","beleg":"Werkstück D.2.5 (Der Kipppunkt; Anwendung & Relevanz: Die eigene Argumentation)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"8c9cfd9df9d629a0","vermerk":"Prüfpult"},"kurz":"Ein Verbot geht am Problem vorbei, denn über Migration lässt sich kaum ohne irgendein Bild sprechen. Kritisch wird ein Bild erst, wenn es ohne Alternativen als einzige Linse steht und Menschen wie eine Naturgewalt erscheinen lässt.","prueffrage":"Welche anderen Wörter benutzen andere Zeitungen für dieselben Zahlen, und was zeigen sie anders?","rueckmeldung":[{"option":1,"text":"Zahlen im Text scheinen ein Gegengewicht zum Bild zu bilden. Im Experiment mit identischer Kriminalstatistik unterschied sich die Zustimmung trotzdem je nach Bild: Korrekte Zahlen heben den Einfluss eines Bildes nicht einfach auf."},{"option":2,"text":"Wörter wie „Flut“ fallen zwar auf, ihre lenkende Wirkung aber kaum: Im Experiment mit identischer Kriminalstatistik nannte fast niemand die Metapher als Einflussfaktor, obwohl die Zustimmung je nach Bild verschieden ausfiel."},{"option":3,"text":"Korrekte Zahlen schließen eine Täuschung durch Zahlen aus, aber keine Lenkung durch Bilder: In einem Experiment mit identischer Kriminalstatistik fiel die Zustimmung je nach Bild verschieden aus. Heikel wird ein Bild, wenn es die einzige Linse ist."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brugman, B. C.; Burgers, C.; Vis, B. (2019): Metaphorical framing in political discourse through words vs. concepts: a meta-analysis. Language and Cognition 11(1), 41–65 (Open Access)","oeffentlich":true,"doi":"10.1017/langcog.2019.5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lakoff, G.; Johnson, M. (1980): Metaphors We Live By. Chicago: University of Chicago Press","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8c9cfd9df9d629a0"}},{"id":"qx-d1-039","clusterId":"D","werkstueckRef":"D.3.1","stufe":1,"question":"Welche Schlussfolgerung ist hier am sinnvollsten?","scenario":"Eine Politikerin fordert in einer Rede, man müsse sich endlich um die „hart arbeitenden Familien in den Vorstädten“ und ihre „Werte“ kümmern. Ein Kommentator wirft ihr vor, sie sende damit verdeckt eine Botschaft an ihre Kernanhänger. Sie entgegnet empört: „Ich habe doch nur von Familien gesprochen! Wieso unterstellst du mir böse Absichten?“ Auffällig ist: Ihre Stammwählerschaft reagiert auf genau diese Formulierungen jedes Mal besonders begeistert, viele andere Zuhörer nehmen sie als Standardfloskel wahr.","options":["Die Reaktion der Stammwählerschaft genügt: Wenn genau diese Formulierungen jedes Mal besonders ankommen, steht fest, dass die Politikerin damit eine verdeckte Botschaft senden wollte.","Die Erklärung der Politikerin gibt den Ausschlag: Sie habe nur von Familien in den Vorstädten und von Werten gesprochen, und was sie meinte, kann letztlich nur sie selbst verlässlich sagen.","Die wörtliche Bedeutung allein entscheidet nichts: Man sollte prüfen, welche Assoziationen die Wörter bei der Zielgruppe wecken, und ob sich diese Deutung im Zusammenhang belegen lässt.","Der Wortlaut der Rede zählt: „Familien“ und „Werte“ sind für sich genommen harmlos, und Vermutungen über Nebenbedeutungen bleiben Spekulation über das, was sie im Stillen gemeint haben könnte."],"correctIndex":2,"explanation":"Eine Botschaft kann auf zwei Kanälen laufen: für die Allgemeinheit harmlos, für Eingeweihte mit zusätzlicher Bedeutung. Das nennt man „Dog Whistling“ (Hundepfeife): Der hohe Ton einer Hundepfeife ist für Menschen unhörbar, für Hunde aber klar wahrnehmbar. Die Sprecherin gewinnt dadurch „plausible Abstreitbarkeit“ (plausible deniability): Sie kann auf den harmlosen Wortlaut verweisen. Die Wörter sind nur der Träger, die Assoziationen im Kopf des Empfängers sind die eigentliche Botschaft. Deshalb sagt der Wortlaut allein wenig. Auch die begeisterte Reaktion der Anhänger beweist die Absicht noch nicht, sie ist nur ein Hinweis, der auch andere Gründe haben kann. Ob wirklich ein Code vorliegt, zeigt sich an Anzeichen wie wiederholter Verwendung, starker Reaktion der Anhänger und dem Kontext bzw. der Geschichte der Phrase. Die Erklärung der Sprecherin ist ein Datenpunkt, gerade bei plausibler Abstreitbarkeit aber kein Maßstab. Der Wortlaut ist ein guter Ausgangspunkt, trägt aber nicht mehr, wenn Anzeichen wie die gleichbleibende Reaktion der Anhänger dagegensprechen. Eine Prüfung auf Tatsachen läuft hier ins Leere, denn die Rede enthält eine Forderung und keine Tatsachenbehauptung.","coreRule":"⚡ Die Botschaft steckt nicht allein im Wort, sondern in dem, was die Eingeweihten darin hören; prüfe darum immer, welchen Code eine Zielgruppe hören könnte und was sich dafür belegen lässt.","beleg":"Werkstück D.3.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Der Wortlaut allein sagt hier wenig, denn die eigentliche Botschaft kann in den Assoziationen der Zielgruppe liegen. Ob ein Code vorliegt, zeigt sich an Anzeichen wie Wiederholung, Reaktion und Kontext, nicht an Wortlaut oder Beteuerung allein.","prueffrage":"Was weißt du über die Absicht der Politikerin sicher, und was schließt du nur aus Reaktionen oder Beteuerungen?","rueckmeldung":[{"option":0,"text":"Die gleichbleibend starke Reaktion der Anhänger ist ein echter Hinweis auf einen Code. Als Beweis der Absicht reicht sie nicht, denn Begeisterung kann auch andere Gründe haben, etwa Zustimmung zur Forderung selbst."},{"option":1,"text":"Ihre Erklärung ist ein Datenpunkt, mehr nicht. Gerade bei einer Botschaft mit plausibler Abstreitbarkeit gehört der Verweis auf den harmlosen Wortlaut zum Mechanismus, er taugt daher kaum als Maßstab für das Gemeinte."},{"option":3,"text":"Der Wortlaut ist ein guter Ausgangspunkt, und die Wörter sind für sich harmlos. Die Wirkung entsteht aber bei den Empfängern, und die gleichbleibende Reaktion der Anhänger lässt sich prüfen, statt sie als bloße Spekulation abzutun."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haney López, I. (2014): Dog Whistle Politics: How Coded Racial Appeals Have Reinvented Racism and Wrecked the Middle Class. New York: Oxford University Press","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4ceec3428b1552c1"}},{"id":"qx-d1-040","clusterId":"D","werkstueckRef":"D.3.1","stufe":2,"question":"Welche Schlussfolgerung ist aus dieser Reaktion gerechtfertigt?","scenario":"Ein Politiker spricht von „den hart arbeitenden Familien in den Vorstädten“ und „ihren Werten“. Eine Journalistin fragt, ob damit bestimmte Gruppen ausgegrenzt werden sollen. Er antwortet empört: „Ich habe doch nur von Familien gesprochen – warum legst du mir böse Dinge in den Mund?“","options":["Die Reaktion macht eine verdeckte Botschaft unwahrscheinlich: Wer sich so empört auf „Familien“ und „Werte“ beruft, meint den Wortlaut vermutlich auch genau so.","Die heftige Gegenwehr ist ein belastbares Indiz, wenn auch kein Beweis: Wer nichts zu verbergen hat, bleibt bei einer Nachfrage der Journalistin meist gelassen.","Die empörte Zurückweisung zeigt nur, dass die Phrase auch harmlos lesbar ist; ob ein Code vorliegt, lässt sie offen und muss am Zusammenhang geprüft werden.","Die Nachfrage der Journalistin war unfair: Sie unterstellt ihm eine verdeckte Botschaft, und das muss er als Redner nicht entkräften, solange nichts belegt ist."],"correctIndex":2,"explanation":"Die Reaktion sagt über die Absicht des Redners wenig. Wer etwas Verdecktes meint, kann sich genau so äußern, denn eine harmlose Oberfläche erlaubt ihm, sich auf den Wortlaut zurückzuziehen und die Verantwortung für die Nebenbedeutung abzuweisen (plausible Abstreitbarkeit). Wer nichts Verdecktes meint, kann sich ebenso äußern, denn ein Unterstellungsvorwurf kann auch zu Unrecht erhoben werden. Ob die Empörung echt oder gespielt ist, lässt sich von außen kaum unterscheiden; sie ist deshalb weder Beweis noch Gegenbeweis. Ob ein Code vorliegt, zeigt erst die Prüfung am Zusammenhang, etwa an einer wiederholten Phrase mit auffällig starker Reaktion der Anhängerschaft, an einer nur Insidern verständlichen Bedeutung und an der Geschichte der Phrase. Die Empörung als Entlastung oder als Belastung zu lesen klingt nachvollziehbar, liest aber aus Tonfall und Wirkung mehr heraus, als sich von außen belegen lässt. Dass die Wörter für sich positiv klingen, ist gerade die Eigenschaft solcher Codes und schließt eine Nebenbedeutung nicht aus. Und eine Nachfrage ist keine unfaire Unterstellung, die man nicht beantworten müsste: Man darf sie stellen, ohne das Ergebnis vorwegzunehmen.","coreRule":"⚡ Empörte Zurückweisung ist ein Warnzeichen, aber kein Beweis, weder für noch gegen eine verdeckte Botschaft.","beleg":"Werkstück D.3.1 (Einstiegsszene; Kontext & Tiefe: plausible Abstreitbarkeit; Red Flags)","status":"entwurf","kurz":"Aus der Empörung lässt sich über die Absicht kaum etwas lesen: Wer etwas Verdecktes meint, kann so reagieren, wer nichts meint, ebenso. Ob ein Code vorliegt, zeigt erst die Prüfung am Zusammenhang.","prueffrage":"Was hat die Journalistin gefragt, und was davon beantwortet der Politiker in seiner Reaktion tatsächlich?","rueckmeldung":[{"option":0,"text":"Dass „Familien“ und „Werte“ harmlos klingen, stimmt. Genau das erlaubt aber, sich auf den Wortlaut zurückzuziehen, und ob die Empörung echt oder gespielt ist, sieht man von außen kaum. Sie beweist weder die eine noch die andere Absicht."},{"option":1,"text":"Auch ein zu Unrecht erhobener Vorwurf kann heftig ablehnende Reaktionen auslösen, nicht nur ein berechtigter. Außerdem ist echte Empörung von gespielter kaum zu unterscheiden. Aus dem Tonfall allein lässt sich daher keine Belastung ableiten."},{"option":3,"text":"Eine Nachfrage ist eine Frage und keine Unterstellung, und sie darf gestellt werden, ohne ihr Ergebnis vorwegzunehmen. Dass ein Vorwurf allein noch nichts belegt, stimmt, aber daraus folgt nicht, dass eine Antwort überflüssig wäre."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Albertson, B. L. (2015): Dog-Whistle Politics: Multivocal Communication and Religious Appeals. Political Behavior 37(1), 3–26","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3cc011373f56e9f2"}},{"id":"qx-d1-041","clusterId":"D","werkstueckRef":"D.3.1","stufe":3,"question":"Woran erkennst du am besten, dass im zweiten Forum aus harmloser Insider-Sprache eine problematische Taktik geworden ist?","scenario":"In einem Forum tauschen sich Angler in ihrem Fachjargon aus, den Außenstehende nicht verstehen. In einem anderen Forum benutzen Nutzer eine scheinbar harmlose Redewendung, die unter Eingeweihten als Erkennungszeichen für Verachtung gegenüber einer Minderheit gilt. Auf Kritik antworten sie empört: „Wir haben doch nur etwas Neutrales gesagt, ihr interpretiert da etwas hinein!“","options":["Die Redewendung bleibt Außenstehenden unverständlich, sodass die Gruppe sich vom Rest abgrenzt und bewusst unter sich bleibt.","Die Redewendung stärkt den Zusammenhalt der Gruppe, weil nur Eingeweihte sie verstehen, und schafft ein Gefühl der Zugehörigkeit.","Die Redewendung verbreitet Vorurteile gegenüber der Minderheit, und die Berufung auf ihre Harmlosigkeit verhindert eine ehrliche Debatte darüber.","Die Redewendung wird von den Nutzern regelmäßig und selbstverständlich verwendet, sodass sie zum festen Bestandteil des Umgangs wird."],"correctIndex":2,"explanation":"Auch der Angler-Jargon schließt Außenstehende aus und ist trotzdem unproblematisch: Insider-Sprache unter Freunden ist harmlos, denn eigene Sprache signalisiert Zugehörigkeit. Dass Außenstehende etwas nicht verstehen, ist also kein Beleg für Böswilligkeit. Dasselbe gilt für Gruppenzusammenhalt, der fast immer mit eigener Sprache einhergeht, und für die regelmäßige, selbstverständliche Verwendung, die jeder Fachjargon zeigt. Entscheidend ist, was der Code tut: Er wird zur toxischen Taktik, wenn er systematisch Vorurteile verbreitet und zugleich eine ehrliche Debatte nahezu unmöglich macht. Die gespielte Empörung auf Kritik schützt den Sprecher dabei vor Verantwortung. Dann ist aus Gruppenkultur eine Taktik der plausiblen Abstreitbarkeit geworden.","coreRule":"⚡ Ein Code unter Freunden ist Gruppenkultur; ein Code, der Vorurteile tarnt und Kritik mit „Ich habe doch nichts gesagt“ abwehrt, ist eine Taktik.","beleg":"Werkstück D.3.1 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist nicht, dass Außenstehende etwas nicht verstehen, sondern was der Code tut: Er verbreitet Vorurteile und blockt zugleich jede ehrliche Debatte ab. Wer wie im Angler-Forum nur Zugehörigkeit stiftet, tut das nicht.","prueffrage":"Welche Merkmale teilt die Redewendung mit dem Angler-Jargon, und worin unterscheidet sie sich von ihm?","rueckmeldung":[{"option":0,"text":"Dass Außenstehende die Redewendung nicht verstehen, trifft genauso auf den Angler-Jargon zu. Abgrenzung nach außen gehört zu fast jeder Gruppensprache und zeigt noch keine böse Absicht."},{"option":1,"text":"Zusammenhalt und Zugehörigkeit sind tatsächlich Wirkungen von Insider-Sprache. Sie zeigen sich aber auch bei den Anglern, wo niemand etwas Problematisches sieht, und erklären daher den Unterschied zwischen beiden Foren nicht."},{"option":3,"text":"Regelmäßiger, selbstverständlicher Gebrauch gehört zu jedem Fachjargon, auch zu dem der Angler. Wie oft ein Ausdruck fällt, sagt noch nichts darüber, ob er Schaden anrichtet."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haney López, I. (2014): Dog Whistle Politics. New York: Oxford University Press","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d07ea50d724a24c5"}},{"id":"qx-d1-042","clusterId":"D","werkstueckRef":"D.3.1","stufe":4,"question":"Welche Deutung der Ergebnisse trägt?","scenario":"Ein Kandidat beendet ein Wahlvideo mit einer Wendung aus einem Kirchenlied, die fast nur Menschen aus bestimmten Pfingstgemeinden als Anspielung erkennen. Ein Experiment mit US-Wählern hat diesen Schlusssatz geprüft: Bei Pfingstchristen, die die Wendung kannten, verbesserte er den Eindruck vom Kandidaten. In einer gemischten Stichprobe, aus der alle herausgenommen wurden, die die Wendung kannten, schadete er dem Kandidaten nicht messbar; derselbe Satz mit dem offenen Zusatz „As I sing in church“ senkte dort Eindruck und Wahlabsicht. Eine Journalistin will aus diesen Ergebnissen erklären, warum Kampagnen solche Anspielungen nutzen.","options":["Die verdeckte Wendung wirkt bei denen, die sie erkennen, und stört die übrigen nicht, weil diese nur einen normalen Satz hören.","Die verdeckte Wendung lohnt sich für Kampagnen kaum, weil sie in der gemischten Stichprobe weder nützte noch schadete.","Die verdeckte Wendung wirkt auch auf Außenstehende, weil sie den religiösen Klang unbewusst aufnehmen, ohne die Anspielung zu kennen.","Die verdeckte Wendung wirkt, weil religiöse Sprache viele Wähler anspricht, wie der bessere Eindruck bei den Pfingstchristen zeigt."],"correctIndex":0,"explanation":"Entscheidend ist, wer die Anspielung überhaupt bemerkt. Wer die Wendung kennt, hört die Botschaft und bewertet den Kandidaten besser. Wer sie nicht kennt, hört einen gewöhnlichen Satz und hat keinen Anlass, sich zu stören. Der offene Zusatz dagegen ist für alle sofort als religiöse Aussage erkennbar und senkte in der gemischten Stichprobe Eindruck und Wahlabsicht. Genau so fiel das Ergebnis des Experiments (Albertson 2015) aus: Bei Pfingstlern, die das Lied kannten, verbesserte die Anspielung den Eindruck vom Kandidaten, ohne die Zuschauer einer gemischten Stichprobe messbar abzuschrecken; derselbe Satz mit offen religiösem Zusatz tat das sehr wohl. Vorbehalt: Es war ein Versuch mit religiöser Sprache in den USA; gemessen wurden Eindruck und Wahlabsicht, die Übertragung auf andere Anspielungen ist eine Annahme.","coreRule":"⚡ Wirkt eine Anspielung nur bei denen, die sie verstehen, stört sie die anderen nicht: Nicht bemerkt heißt nicht wirkungslos.","beleg":"Werkstück D.3.1 (Anwendung & Relevanz: In der Politik); Fn. gl-d-albertson. Albertson, B. L. (2015): Dog-Whistle Politics: Multivocal Communication and Religious Appeals. Political Behavior 37(1), 3–26, https://doi.org/10.1007/s11109-013-9265-x (Stichprobe 1: 402 Pfingstchristen, 84 % kannten die Wendung „wonder-working power“; Stichprobe 2: 783 Befragte, ohne die 24 %, die sie kannten; offener Zusatz „As I sing in church“; gelesen 12.10.2026 im Volltext, S. 9–14).","status":"entwurf","kurz":"Wer die Wendung erkennt, hört die Botschaft und bewertet den Kandidaten besser; wer sie nicht kennt, hört einen gewöhnlichen Satz und stört sich nicht. Offen ausgesprochen wirkt derselbe Gedanke dagegen für alle religiös und schadete im Versuch.","prueffrage":"Welche Befragten konnten in der gemischten Stichprobe die Wendung überhaupt als Anspielung hören, und wie unterscheidet sich der Satz mit Zusatz davon?","rueckmeldung":[{"option":1,"text":"Ein fehlender Effekt in der gemischten Stichprobe klingt nach Misserfolg. Dort fehlten aber alle Kenner, also die eigentliche Zielgruppe; dass die Anspielung nicht schadete, ist gerade ihr Vorteil gegenüber dem offenen Zusatz."},{"option":2,"text":"Ein Einfluss auf Außenstehende wäre eine auffällige Erklärung, doch gemessen wurde keiner: Bei ihnen zeigte sich weder Nutzen noch Schaden. Ein unbewusstes Aufnehmen des religiösen Klangs wird durch die Ergebnisse nicht gestützt."},{"option":3,"text":"Dass der Eindruck bei den Pfingstchristen stieg, stimmt. Daraus lässt sich aber nicht auf viele Wähler schließen: Der offen religiöse Zusatz senkte in der gemischten Stichprobe Eindruck und Wahlabsicht. Auf das Erkennen der Anspielung kommt es an, nicht auf religiöse Sprache an sich."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Albertson, B. L. (2015): Dog-Whistle Politics: Multivocal Communication and Religious Appeals. Political Behavior 37(1), 3–26","oeffentlich":false},{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5ea622cbfcf1daaa"}},{"id":"qx-d1-043","clusterId":"D","werkstueckRef":"D.3.2","stufe":1,"question":"Wie reagierst du am klügsten auf diesen Gesprächsverlauf?","scenario":"In einer Diskussion über Staatsfinanzen sagt jemand: „Alle Steuern sind Diebstahl. Der Staat nimmt den Menschen mit Gewalt, was ihnen gehört.“ Du widersprichst und führst an, dass Straßen, Schulen und Gerichte aus Steuern bezahlt werden. Er antwortet: „Ich sage ja nur, dass die Regierung sparsam mit dem Geld der Bürger umgehen sollte. Willst du etwa Verschwendung verteidigen?“ Du merkst, dass du dem zweiten Satz kaum widersprechen kannst.","options":["Du stimmst zu, dass sparsames Haushalten wichtig ist, und fragst, ob er weiterhin hinter seiner ersten Aussage steht, dass alle Steuern Diebstahl sind.","Du legst mit Haushaltszahlen aus den letzten Jahren dar, dass der Staat nicht verschwenderisch wirtschaftet, und entkräftest so seinen Vorwurf der Verschwendung.","Du schlägst vor, über die gerechte Verteilung der Steuerlast zu sprechen, und lenkst das Gespräch auf einen Punkt, bei dem ihr konkrete Reformen vergleichen könnt.","Du suchst den gemeinsamen Nenner, dass sparsames Haushalten wichtig ist, und beendest das Gespräch dort, damit es nicht in einen Streit ausartet."],"correctIndex":0,"explanation":"Der Sprecher hat zwei Aussagen gemacht, die verschieden stark sind: eine radikale („Alle Steuern sind Diebstahl“), die schwer zu verteidigen ist, und eine harmlose („sparsam umgehen“), der fast jeder zustimmt. Unter Druck weicht er auf die harmlose aus und tut so, als habe er nie mehr gesagt. Wer nun nur die harmlose Aussage diskutiert, greift ins Leere, und der Sprecher kehrt später unbemerkt zur starken Behauptung zurück. Klug ist es, der unstrittigen Aussage ehrlich zuzustimmen und dann zur ursprünglichen, starken Behauptung zurückzuführen: „Stehst du noch zu deiner ersten Aussage?“ Dann muss er sich entscheiden. Entweder er verteidigt die radikale Aussage und trägt die argumentativen Kosten, oder er nimmt sie zurück. Beides ist ein ehrliches Ergebnis. Dieses Muster ist als Motte-and-Bailey-Täuschung bekannt (benannt nach der mittelalterlichen Burg: schwer zu verteidigende Vorburg, gut zu haltender Turmhügel; geprägt vom Philosophen Nicholas Shackel 2005). Ob die Regierung tatsächlich sparsam wirtschaftet, ist eine andere Frage und löst das Problem des Positionswechsels nicht. Auch ein Gespräch über die Verteilung der Steuerlast kann sinnvoll sein, lässt die erste Behauptung aber unberührt. Und im gemeinsamen Nenner zu enden wirkt versöhnlich, lässt aber offen, ob er zu seiner starken Aussage steht.","coreRule":"⚡ Stimm der harmlosen Aussage zu, aber bring das Gespräch zur ursprünglichen, starken Behauptung zurück und lass sie bestätigen oder zurücknehmen.","beleg":"Werkstück D.3.2 (Kontext & Tiefe); Fn. gl-d-shackel (Shackel 2005, Metaphilosophy 36(3), S. 295–320)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"2d479639d47d878e","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Stimm dem Unstrittigen ehrlich zu und führe dann zur ersten Aussage zurück: Er muss sich nun entscheiden, ob er sie verteidigt oder zurücknimmt. Der Denkfehler wäre, nur über die harmlose Aussage zu streiten, denn die starke bliebe unberührt.","prueffrage":"Worüber habt ihr am Anfang gestritten, und worüber würdet ihr nach seiner Antwort streiten?","rueckmeldung":[{"option":1,"text":"Ob der Staat sparsam wirtschaftet, ist eine eigene Frage, die sich prüfen lässt. Behauptet hat er aber nur, die Regierung solle sparsam sein; dagegen anzuargumentieren trifft nichts, und die Aussage „Alle Steuern sind Diebstahl“ bleibt unberührt."},{"option":2,"text":"Über die Verteilung der Steuerlast zu reden kann durchaus lohnen und ist konkret. Die erste, radikale Behauptung bleibt dabei aber stehen, und er muss nie sagen, ob er sie noch vertritt."},{"option":3,"text":"Die Zustimmung zur Sparsamkeit ist ehrlich, und das Gespräch endet friedlich. Offen bleibt aber, ob er zu „Alle Steuern sind Diebstahl“ steht, und er kann später unbemerkt dorthin zurückkehren."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3), 295–320","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2d479639d47d878e"}},{"id":"qx-d1-044","clusterId":"D","werkstueckRef":"D.3.2","stufe":2,"question":"Wie reagierst du am klügsten?","scenario":"Dein Gegenüber behauptet: „Homöopathie kann Grippe heilen.“ Du fragst nach Belegen. Er antwortet: „Ich sage ja nur, dass es den Placebo-Effekt wirklich gibt.“ Kurz darauf redet er wieder davon, dass man mit Homöopathie auf Medikamente gegen die Grippe verzichten könne.","options":["Der vernünftigen Aussage über den Placebo-Effekt zustimmen und ihn dann fragen, ob er weiterhin zu seiner ursprünglichen Heilungsbehauptung steht.","Den Placebo-Effekt in Frage stellen und ihm erklären, dass Scheinbehandlungen bei einer Grippe nichts bewirken, damit er seine Heilungsbehauptung zurücknimmt.","Ihn bitten, den Placebo-Effekt bei Grippe genauer zu erläutern, damit klar wird, wie weit seine scheinbar harmlose Aussage zur Heilung reicht.","Ihn nach Quellen zum Placebo-Effekt fragen, bevor du ihm zustimmst, denn auch eine harmlos klingende Aussage sollte man vor der Zustimmung prüfen."],"correctIndex":0,"explanation":"Hier wechselt jemand von einer starken, schwer zu belegenden Behauptung („heilt Grippe“) zu einer harmlosen, kaum bestreitbaren („den Placebo-Effekt gibt es wirklich“) und kehrt später zur starken zurück. Dieses Muster heißt Motte-and-Bailey, nach der mittelalterlichen Burg mit schwer haltbarem Vorhof (Bailey) und gut zu verteidigendem Turmhügel (Motte). Die harmlose Aussage zu bekämpfen führt ins Leere: Sie ist vernünftig und weithin akzeptiert, und gegen sie lässt sich kaum argumentieren. Der Ausweg ist, ihr zuzustimmen und die ursprüngliche Behauptung festzunageln („Pinning Down the Bailey“): „Stehst du noch zu deiner ersten Aussage?“ So muss er sich entscheiden. Entweder er verteidigt die starke Behauptung und muss Belege liefern, oder er gibt sie offen auf. Eine Meinung im Gespräch abzuschwächen ist ein Zeichen intellektueller Ehrlichkeit. Motte-and-Bailey ist das Gegenteil, weil der Rückzug nur ein Fluchtweg ist und die radikale Position danach unauffällig zurückkehrt. Den Placebo-Effekt zu bestreiten führt ins Leere: Er existiert, und der Streit darüber ließe die Heilungsbehauptung unberührt. Ihn den Placebo-Effekt genauer erläutern zu lassen oder nach Quellen dafür zu fragen ist an sich sinnvoll, bleibt aber bei der harmlosen Aussage, statt die starke zu prüfen. Und die Frage nach finanziellen Interessen sagt nichts darüber, ob die Heilungsbehauptung stimmt.","coreRule":"⚡ Stimm der harmlosen Aussage zu und frag nach der starken.","beleg":"Werkstück D.3.2 (Das Anti-Denkmuster; Anwendung & Relevanz: Pseudomedizin & Esoterik)","status":"entwurf","kurz":"Der Placebo-Effekt ist real und unbestritten; ihn zu bekämpfen führt ins Leere. Stimm ihm zu und frag, ob er noch zur ersten Aussage steht: Dann muss er die Heilungsbehauptung belegen oder offen aufgeben.","prueffrage":"Wie verhält sich der Satz über den Placebo-Effekt zu dem, was er vorher und nachher über Homöopathie sagt?","rueckmeldung":[{"option":1,"text":"Den Placebo-Effekt gibt es wirklich, ihn zu bestreiten ist ein Kampf, den du nicht gewinnst. Außerdem ließe der Streit darüber die Heilungsbehauptung völlig unberührt, um die es eigentlich geht."},{"option":2,"text":"Die Nachfrage ist an sich sinnvoll, bleibt aber bei der harmlosen Aussage. Er kann sie ausführlich erläutern, ohne sich zur Heilung zu äußern, und die starke Behauptung wird weiter nicht geprüft."},{"option":3,"text":"Quellen zu verlangen ist grundsätzlich gut. Hier prüfst du damit aber nur die unstrittige Aussage über den Placebo-Effekt, nicht die Heilungsbehauptung, die tatsächlich der Belege bedarf."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6abfc01a3716d5fc"}},{"id":"qx-d1-045","clusterId":"D","werkstueckRef":"D.3.2","stufe":3,"question":"Was ist an seinem Vorgehen fehlerhaft?","scenario":"Ein Kollege behauptet im Meeting: „Unser neues Lernprogramm macht jeden Mitarbeiter innerhalb einer Woche zum Top-Verkäufer.“ Du fragst nach Belegen. Er antwortet: „Ich habe nur gesagt, dass Weiterbildung grundsätzlich sinnvoll ist.“ Du stimmst zu. Kurz darauf wirbt er im Team wieder dafür, dass das Programm jeden zum Top-Verkäufer macht.","options":["Er verallgemeinert zu stark, denn dass ein Programm jeden Mitarbeiter binnen einer Woche zum Top-Verkäufer macht, ist eine kaum haltbare Übertreibung.","Er hat sich nur zum Schein auf die harmlose Aussage zurückgezogen und die kühne Behauptung danach wieder vertreten, als wäre nichts gewesen.","Er lenkt vom Thema ab, indem er auf Weiterbildung allgemein umschwenkt, statt die Frage nach Belegen für sein Programm zu beantworten.","Er hat seine Behauptung sofort abgeschwächt, als du nach Belegen gefragt hast, und damit eingeräumt, dass er sie gar nicht belegen kann."],"correctIndex":1,"explanation":"Seine Behauptung hat sich nie geändert: Unter Kritik wich er auf eine leicht zu verteidigende Aussage aus, die kaum jemand bestreitet, und kehrte danach unauffällig zur kühnen Behauptung zurück. Dadurch wurde die starke Aussage nie wirklich geprüft. Eine Position abzuschwächen ist an sich ehrlich, wenn man die starke Aussage dauerhaft aufgibt. Hier wurde sie nur vorübergehend versteckt. Zum Prüfen hilft die Frage, ob er noch zur ursprünglichen Aussage steht: Wer sie bejaht, muss Belege liefern, wer sie verneint, hat sie aufgegeben. Dieses Muster heißt Motte-and-Bailey: Bei Kritik zieht man sich in die gut zu verteidigende „Motte“ zurück, die kühne „Bailey“ nimmt man später wieder ein.","coreRule":"⚡ Zurückrudern ist ehrlich, wenn die Position dauerhaft geräumt wird, nicht, wenn sie heimlich zurückkehrt.","beleg":"Werkstück D.3.2 (Kernidee; Der Kipppunkt; Red Flags)","status":"entwurf","kurz":"Er hat die kühne Aussage unter Kritik nur versteckt, nicht aufgegeben, und sie danach unauffällig wieder vertreten. So wurde sie nie geprüft. Wer abschwächt, ohne die starke Aussage dauerhaft fallen zu lassen, hat sich nur kurz in eine leichte Position zurückgezogen.","prueffrage":"Was behauptet er im Meeting, was nach deiner Frage nach Belegen und was später im Team?","rueckmeldung":[{"option":0,"text":"Die Behauptung ist tatsächlich stark übertrieben. Das beschreibt aber die Aussage, nicht sein Vorgehen: Der eigentliche Fehler liegt darin, dass er sie unter Kritik versteckt und danach unverändert wieder vorbringt."},{"option":2,"text":"Das Ausweichen auf Weiterbildung allgemein stimmt und beantwortet deine Frage nach Belegen nicht. Dabei bliebe es aber nicht: Entscheidend ist, dass er danach zur kühnen Behauptung zurückkehrt, als wäre sie nie infrage gestellt worden."},{"option":3,"text":"Eine echte Abschwächung wäre ehrlich, wenn er die starke Aussage dauerhaft aufgäbe. Hier hat er sie nur vorübergehend ersetzt und danach wieder vertreten, daher ist es weder ein Eingeständnis noch eine wirkliche Abschwächung."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"66ed31704e8db1d0"}},{"id":"qx-d1-046","clusterId":"D","werkstueckRef":"D.3.2","stufe":4,"question":"Was ist an diesem Gesprächsverlauf aus Sicht der Prüfbarkeit das eigentliche Problem?","scenario":"In einer Diskussion behauptet jemand: „Unsere Methode heilt jede Krankheit, auch Krebs.“ Du fragst nach kontrollierten Studien. Er antwortet: „Ich meine ja nur, dass eine positive Einstellung wichtig für den Heilungsprozess ist.“ Du stimmst zu, und prompt sagt er wieder: „Siehst du, deshalb heilt unsere Methode eben jede Krankheit.“","options":["Die starke Behauptung wird bei Kritik nicht aufrechterhalten: Sie weicht einer harmlosen und kehrt danach unverändert zurück, sodass sie sich einer Widerlegung entzieht.","Die starke Behauptung „jede Krankheit, auch Krebs“ ist so weit gefasst, dass sie nichts ausschließt und sich mit keiner denkbaren Beobachtung widerlegen lässt.","Die starke Behauptung bleibt unbelegt, weil er deine Frage nach Studien übergeht; prüfbar würde sie, sobald er die von dir verlangten kontrollierten Studien vorlegen kann.","Die starke Behauptung lässt sich kaum prüfen, weil Heilung auch von der Einstellung abhängt und sich die Wirkung einer einzelnen Methode davon schwer trennen lässt."],"correctIndex":0,"explanation":"Eine Behauptung ist nur dann prüfbar, wenn man sagen kann, was sie ausschließt und woran sie scheitern würde. Hier geschieht das Gegenteil: Sobald es um Belege geht, verschwindet die kühne These und eine harmlose Aussage tritt an ihre Stelle, die kaum jemand bestreitet. Danach taucht die kühne These unverändert wieder auf, als wäre nichts gewesen. So wird sie nie wirklich getestet und kann nie scheitern, obwohl sie nie bestanden hat. Dass die harmlose Aussage stimmt, sagt nichts über die starke aus: Dass eine positive Einstellung beim Genesen helfen kann, belegt nicht, dass eine Methode Krebs heilt. Wirksam ist, die Debatte zur ursprünglichen Behauptung zurückzuführen: „Der gemäßigten Aussage stimme ich zu. Stehst du noch zu deiner ersten, viel stärkeren Behauptung? Denn sie war mein Kritikpunkt.“ Erst dann muss er sich entscheiden: belegen oder zurücknehmen.","coreRule":"⚡ Wer seine kühne These bei Kritik unsichtbar macht, entzieht sie der Widerlegung. Hake bei der ursprünglichen Behauptung nach, nicht beim Rückzugsort.","beleg":"Werkstück D.3.2 (Verbindungen: Falsifizierbarkeit; Anti-Denkmuster)","status":"entwurf","kurz":"Bei der ersten Kritik tauscht er die kühne Behauptung gegen eine harmlose aus und holt die kühne danach unverändert zurück. So wird sie nie geprüft und kann nie scheitern. Dass die harmlose stimmt, sagt über die starke nichts.","prueffrage":"Woran müsste die Behauptung „heilt jede Krankheit“ scheitern können, und bekommt sie im Gespräch überhaupt eine Gelegenheit dazu?","rueckmeldung":[{"option":1,"text":"Eine so weit gefasste Aussage ist tatsächlich schwer zu halten. Ein einziger Fall, in dem die Methode nicht heilt, würde sie aber widerlegen. Das Problem liegt im Gesprächsverlauf: Bei Kritik wird ausgewichen, danach kehrt dieselbe These zurück."},{"option":2,"text":"Dass keine Studien genannt werden, ist richtig beobachtet, die Behauptung bleibt unbelegt. Das Wesentliche ist aber das Ausweichen: Statt Belege zu liefern, tritt eine harmlose Aussage an die Stelle der starken, und diese kehrt danach unverändert zurück."},{"option":3,"text":"Eine positive Einstellung kann beim Genesen tatsächlich helfen. Das macht die Methode aber nicht schwer prüfbar: Kontrollierte Studien könnten ihre Wirkung gerade von solchen Einflüssen trennen. Die harmlose Aussage belegt die starke nicht, und genau diese wird umgangen."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1afae219c0bf90d3"}}]`);export{t as n,n as t};